/**
 * Documentation object for a CAOS command parameter
 */
@JsExport
@JsName("ICaosParameter")
@Serializable
data class ICaosParameter(
    /**
     * Argument index within a command call
     */
    @JsName("index")
    val index: Int,
    /**
     * The human-readable name of this parameter
     */
    @JsName("name")
    val name: String,

    /**
     * The internal value type id
     */
    @JsName("typeId")
    val typeId: Int,

    /**
     * The human-readble type name
     */
    @JsName("type")
    val typeName: String,

    /**
     * The id of this parameters known values (if any)
     * This would be the id to the CHEMICALS values list for the chemical parameter for `CHEM`
     */
    @JsName("valuesListId")
    val valuesListId: Int? = null,

    /**
     * The name of the values list
     */
    @JsName("valuesListName")
    val valuesListName: String? = null,
) {
    internal constructor(parameter: CaosParameter, variant: String) : this(
        parameter.index,
        parameter.name,
        parameter.typeId,
        parameter.type.simpleName,
        valuesListId = parameter.valuesListIds?.get(variant),
        valuesListName = parameter.valuesListIds?.get(variant)?.let { valuesListId ->
            CaosLibs[variant].valuesList(valuesListId)?.name
        }
    )

    /**
     * The associated values list
     */
    val valuesList: CaosValuesList?
        get() {
            return if (valuesListId != null) {
                getValuesList(valuesListId)
            } else {
                null
            }
        }
}


/**
 * A documentation object for a CAOS command
 */
@JsExport
@JsName("ICaosCommand")
@Serializable
data class ICaosCommand(
    /**
     * The command word or words
     */
    @JsName("command")
    val command: String,

    /**
     * The list of parameters as documentation objects
     */
    @JsName("parameters")
    val parameters: Array<ICaosParameter>,

    /**
     * Whether this command can function as an lvalue
     */
    @JsName("isLvalue")
    val isLvalue: Boolean,

    /**
     * Whether this command can function as an rvalue
     */
    @JsName("isRvalue")
    val isRvalue: Boolean,

    /**
     * Whether this command is block level and cannot be used as an r/l value
     */
    @JsName("isCommand")
    val isCommand: Boolean = !(isRvalue || isLvalue),

    /**
     * The internal type id for what this command returns.
     * Returns 8 for non-r/l values
     */

    @JsName("returnTypeId")
    val returnTypeId: Int,

    /**
     * The human-readable name for the return type such as "integer", "float", "string"
     */
    @JsName("returnTypeName")
    val returnTypeName: String,

    /**
     * Which variants this specific implemenation of this command is valid for
     * Some commands have the same command word, but different parameters or meaning
     */
    @JsName("variants")
    val variants: Array<String>,

    /**
     * A description of what this commadn does
     */
    @JsName("description")
    val description: String?,

    /**
     * The name for the value that follows this in SETV when used as lvalue
     */
    @JsName("lvalueName")
    val lvalueName: String? = null,

    /**
     * Values list associated with this command scoped by variant
     */
    @JsName("returnValuesListIds")
    val returnValuesListIds: VariantData<Int>? = null,

    /**
     * Whether this command requires an owner object
     */
    @JsName("requiresOwnr")
    val requiresOwnr: Int = 0,

    /**
     * The group this command is associated with such as "physics", "creatures", "sprites"
     */
    @JsName("commandGroup")
    val commandGroup: String,

    /**
     * The format to use when folding a doif equality statement into easier to understand text
     */
    @JsName("doifFormat")
    val doifFormat: String? = null,

    /**
     * Whether this command must be used in the context of a Creature owner
     */
    @JsName("requiresCreatureOwnr")
    val requiresCreatureOwnr: Boolean = false,
) {

    /**
     * Get the return values list for this variant
     */
    @JsName("returnValuesList")
    fun returnValuesList(variant: String): CaosValuesList? {
        val listId = returnValuesListIds?.get(variant)
            ?: return null
        return getValuesList(listId)
    }

    /**
     * Custom equals to deal with the arrays parameter
     */
    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is ICaosCommand) return false

        if (command != other.command) return false
        if (!parameters.contentEquals(other.parameters)) return false
        if (isLvalue != other.isLvalue) return false
        if (isRvalue != other.isRvalue) return false
        if (isCommand != other.isCommand) return false
        if (returnTypeId != other.returnTypeId) return false
        if (returnTypeName != other.returnTypeName) return false
        if (!variants.contentEquals(other.variants)) return false
        if (description != other.description) return false
        if (lvalueName != other.lvalueName) return false
        if (returnValuesListIds != other.returnValuesListIds) return false
        if (requiresOwnr != other.requiresOwnr) return false
        if (commandGroup != other.commandGroup) return false
        if (doifFormat != other.doifFormat) return false
        if (requiresCreatureOwnr != other.requiresCreatureOwnr) return false

        return true
    }

    /**
     * Custom hashcode implementation to handle array values in object
     */
    override fun hashCode(): Int {
        var result = command.hashCode()
        result = 31 * result + parameters.contentHashCode()
        result = 31 * result + isLvalue.hashCode()
        result = 31 * result + isRvalue.hashCode()
        result = 31 * result + isCommand.hashCode()
        result = 31 * result + returnTypeId
        result = 31 * result + returnTypeName.hashCode()
        result = 31 * result + variants.contentHashCode()
        result = 31 * result + (description?.hashCode() ?: 0)
        result = 31 * result + (lvalueName?.hashCode() ?: 0)
        result = 31 * result + (returnValuesListIds?.hashCode() ?: 0)
        result = 31 * result + requiresOwnr
        result = 31 * result + commandGroup.hashCode()
        result = 31 * result + (doifFormat?.hashCode() ?: 0)
        result = 31 * result + requiresCreatureOwnr.hashCode()
        return result
    }

}

/**
 * Converts a concreate command into the format used by JS implentations
 */
internal fun CaosCommand.toJsCommand(variant: String): ICaosCommand {
    return ICaosCommand(
        command = command,
        parameters = parameters.map {
            ICaosParameter(it, variant)
        }.sortedBy { it.index }.toTypedArray(),
        isLvalue = lvalue,
        isRvalue = rvalue,
        returnTypeId = returnType.value,
        returnTypeName = returnType.simpleName,
        variants = variants,
        description = description,
        commandGroup = commandGroup,
        doifFormat = doifFormat,
        lvalueName = lvalueName,
        requiresCreatureOwnr = requiresCreatureOwnr,
        requiresOwnr = requiresOwnr,
        returnValuesListIds = returnValuesListIds?.let { VariantData(it) },
        isCommand = isCommand,
    )
}

/**
 * 32-bit uint descriptors of the type of parser token represented
 */
@JsExport
@Serializable
object TypeTokens {
    val FLOAT = token("flot")
    val INT = token("int_")
    val CHAR = token("char")
    val BINARY = token("bina")
    val BYTE_STRING = token("byte")
    val QUOTE_STRING = token("qstr")
    val BRACKET_STRING = token("bstr")
    val TOKEN = token("tokn")
    val EQ_JOIN = token("eqjn")
    val EQ_OP = token("eqop")
    val PICT_DIMENSION = token("pict")
    val ERROR = token("errr")
    val INDEXED_VARIABLE = token("var_")
    val COMMAND_TOKEN = token("cmnd")
    val PLACEHOLDER_TOKEN = token("plch")
    val COMMENT = token("****")
    val CAOS2_COMMENT = token("*###")
    val NEWLINE = token("\\r\\n")
    val SPACES = token("_WS_")
}

/**
 * Codes for the kind of error represented
 */
@JsExport
@JsName("ErrorTypes")
@Serializable
object ErrorTypes {
    const val GENERAL = 0
    const val TYPE_ERROR = 1
    const val INCOMPLETE_COMMAND_ERROR = 2
    const val OUT_OF_VARIANT = 3
    const val UNTERMINATED_CONTROL_STATEMENT = 4
    const val UNEXPECTED_CONTROL_TERMINATOR = 5
    const val WHITESPACE_ERROR = 6
    const val TOO_MANY_NEWLINES = 7
}


/**
 * A concrete holder for data associated with a variant
 * Using a MAP failed under JS
 */
@Suppress("PropertyName")
@JsExport
@Serializable
data class VariantData<T>(
    @JsName("C1")
    val C1: T? = null,
    @JsName("C2")
    val C2: T? = null,
    @JsName("CV")
    val CV: T? = null,
    @JsName("C3")
    val C3: T? = null,
    @JsName("DS")
    val DS: T? = null,
    @JsName("SM")
    val SM: T? = null
) {

    /**
     * Constructs an object using a MAP indexed by CAOS variant codes
     */
    internal constructor(map: Map<String, T>): this(
        C1 = map["C1"],
        C2 = map["C2"],
        CV = map["CV"],
        C3 = map["C3"],
        DS = map["DS"],
        SM = map["SM"]
    )


    /**
     * Gets the value given a caos variant object
     */
    @JsName("valueForVariant")
    operator fun get(variant: CaosVariant): T? {
        return when(variant) {
            CaosVariant.C1 -> C1
            CaosVariant.C2 -> C2
            CaosVariant.CV -> CV
            CaosVariant.C3 -> C3
            CaosVariant.DS -> DS
            CaosVariant.SM -> SM
            else -> null
        }
    }

    /**
     * Get value for given variant string
     */
    operator fun get(variant: String): T? {
        return when(variant.uppercase()) {
            "C1" -> C1
            "C2" -> C2
            "CV" -> CV
            "C3" -> C3
            "DS" -> DS
            "SM" -> SM
            else -> null
        }
    }
}