package com.bedalton.creatures.caos.libs

import com.bedalton.common.self
import com.bedalton.creatures.caos.utils.Log
import kotlin.js.Promise

external interface SelfWithLibs {
    var caosLibUrl: String?
    var universalLibTemp: dynamic

}

private val mSelf: SelfWithLibs?
    get() = if (js("typeof self != 'undefined'") as Boolean) {
        js("self").unsafeCast<SelfWithLibs>()
    } else if (js("typeof global == 'object'") as Boolean) {
        js("global").unsafeCast<SelfWithLibs>()
    } else if (js("typeof window != 'undefined'") as Boolean) {
        js("window").unsafeCast<SelfWithLibs>()
    } else {
        Log.warn("libURL", "self is not defined in JS context")
        null
    }

private val mRequire: ((String) -> String)? by lazy {
    js("require != null ? require : null")
}

private val caosLibUrlNonNull get() = mSelf?.caosLibUrl ?: "./caos.universal.lib.json"

val universalLibString: String by lazy {

    val libTemp = js("universalLibTemp != null ? universalLibTemp : null")
        ?: mSelf?.universalLibTemp

    if (libTemp != null) {
        return@lazy JSON.stringify(libTemp)
    }

    if (mRequire != null) {
        return@lazy mRequire!!.invoke(caosLibUrlNonNull)
    }

    preloadedUniversalLib
        ?: throw NullPointerException("CAOS Lib not preloaded")

}


private var preloadedUniversalLib: String? = null


private var preloading: Boolean = run {
    if (mRequire != null) {
        return@run false
    }
    if (js("universalLibTemp != null") as Boolean) {
        return@run true
    }
    preloadLib()
    true
}

internal fun preloadLib(): Promise<Boolean> {

    if (preloadedUniversalLib != null) {
        return Promise.resolve(true)
    }
    val url = caosLibUrlNonNull
    return self.fetch(url)
        .then { r ->
            r.body
        }
        .then { text: String ->
            preloadedUniversalLib = text
            preloading = false
            true
        }
        .catch { e ->
            Log.e("preloadLib", "Failed to preload lib; " + e.message)
            preloading = false
            false
        }
}

/**
 * Holds universal CAOS lib definitions.
 * Needs to be loaded by external JS file
 */
internal actual val universalLib: CaosLibDefinitions by lazy {
    json.decodeFromString(CaosLibDefinitions.serializer(), universalLibString)
}

