@file:Suppress("unused")

package com.bedalton.common.util

import kotlin.js.Date
import kotlin.math.floor

actual fun localGMTOffsetInMinutes(): Long? {
    return Date().getTimezoneOffset().toLong()
}

@JsExport
actual fun unixToDateComponents(unix: Double): DateComponents {
    val date = Date(unix)
    return DateComponents(
        date.getFullYear(),
        date.getMonth(),
        date.getDate(),
        date.getHours(),
        date.getMinutes(),
        date.getSeconds(),
        unix
    )
}

@JsExport
actual fun toUnixTime(dateComponents: DateComponents, offsetHours: Int?, offsetMinutes: Int?): Double {
    val date = Date(dateComponents.toISO())
    val time: Long = date.getTime().toLong()
    val out = if (offsetHours != null || offsetMinutes != null) {
        val offset = ((offsetHours ?:0) * 60) + (offsetMinutes ?: 0)
        time + offset
    } else {
        time
    }
    return floor(out / 1000.0)
}