package com.bedalton.log


/**
 * Run log callback if mode is set to true
 */
fun Log.ifLog(mode: String, callback: () -> Unit) {
    if (!silent && hasMode(mode)) {
        callback()
    }
}

/**
 * Run log callback if meeting the given log level is enabled
 */
fun Log.ifLog(level: LogLevel, callback: () -> Unit) {
    if (!silent && level.value >= logLevel.value) {
        callback()
    }
}

/**
 * Log info message if mode is set to true
 */
fun Log.iIf(mode: String, replace: Boolean = false, color: LoggerColor? = null, callback: () -> String) {
    if (!silent && hasMode(mode)) {
        i(replace, color, callback)
    }
}

