enum class EqualityInlayHints(
    override val option: String,
    override val description: String,
    override val priority: Int = 5
) : EqualityInlayHintsProvider {

    /**
     * Provides hint for return values of expression, mostly for comparisons
     *
     */
    ATTRIBUTE_BITFLAGS_IN_EQUALITY_EXPRESSIONS("bitflagValues","Show bit flag for equality expressions", 100) {
        override fun isApplicable(variant: CaosVariant, element: EqualityStatement): Boolean {
            val other = (if (isInteger(element.first)) {
                element.second
            } else if (isInteger(element.second)) {
                element.first
            } else {
                return false
            }) ?: return false
            return usesBitFlags(variant, other)
        }

        private fun isInteger(element: Argument?): Boolean {
            return element != null && ((element.parserItem as? IntVal)?.value ?: 0) > 0
        }

        private fun usesBitFlags(variant: CaosVariant, element: Argument): Boolean {
            val commandString = (element as? CommandCall)?.command
                ?: return false
            // Check if value is cached for this list
            val commandDefinition = CaosLibs[variant][CommandType.RVALUE, commandString.command]
                ?: return false

            // Get return values list if any
            val valuesList = commandDefinition.first.returnValuesList[variant]
                ?: return false
            // Return true if is bitflag
            return valuesList.bitflag
        }

        override fun provideHints(variant: CaosVariant, element: EqualityStatement): List<InlayHint> {
            // Ensure element is RValue, though that should have been checked in isApplicable()
            val expression = (if (element.first?.parserItem is IntVal) {
                element.first
            } else {
                element.second
            }) ?: return EMPTY_INLAY_LIST


            val bitFlagValue = expression.text.toIntOrNull()
                ?: return EMPTY_INLAY_LIST

            // If value is not greater than 0, then it does not matter if it is bitflags or not
            if (bitFlagValue < 1) {
                return EMPTY_INLAY_LIST
            }

            val typeList = getOpposingValuesList(variant.code, element, expression)
                ?: return EMPTY_INLAY_LIST

            val position = expression.end()

            // Generate bit-flag inlay hints
            return getBitFlagHintValues(typeList, bitFlagValue, position)
        }

