    },

    /**
     * Gets assumed argument name for an equality expression rvalue
     * i.e. chem 4 (coldness)
     */
    ASSUMED_EQ_VALUE_NAME_HINT("equalityValueName", "Show assumed value name in Equality expression", 90) {
        override fun isApplicable(variant: GameVariant, element: EqualityStatement): Boolean {
            return ((element.first?.parserItem is IntVal || element.first?.parserItem is ParserItem.C2eStringVal) && element.second is CommandCall) ||
                    ((element.second?.parserItem is IntVal || element.second?.parserItem is ParserItem.C2eStringVal) && element.first is CommandCall)
        }

        /**
         * Provide hints for assumed literal values named value
         */
        override fun provideHints(variant: GameVariant, element: EqualityStatement): List<InlayHint> {
            val firstIsInt = (element.first?.parserItem is IntVal || element.first?.parserItem is ParserItem.C2eStringVal)

            val value = (if (firstIsInt) {
                element.first!!.text
            } else {
                element.second!!.text
            })

            val commandCall = (if (firstIsInt) {
                element.second as? CommandCall
            } else {
                element.first as? CommandCall
            }) ?: return EMPTY_INLAY_LIST

            val valuesList = commandCall.command.returnValuesList(variant.code)
                ?: return EMPTY_INLAY_LIST

            if (value == "0" && valuesList.name.uppercase().let { it.startsWith("CHEM") || it.startsWith("DRIVE") })
                return EMPTY_INLAY_LIST

            // Get corresponding value for argument value in list of values
            val valuesListValue = valuesList[value]
                ?: return EMPTY_INLAY_LIST

            val position = if (firstIsInt) {
                element.first!!.end()
            } else {
                element.second!!.end()
            }

            // Format hint and return
            return listOf(InlayHintImpl(position, "(" + valuesListValue.name + ")"))
        }

