/**
 * Gets the command token from the opposing side of an equality comparison
 */
private fun getOpposingValuesList(
    variant: String,
    parent: EqualityStatement,
    expression: Argument
): CaosValuesList? {
    val other = if (parent.first == expression) parent.second else parent.first
    return (other as? CommandCall)?.command?.returnValuesList(variant)
}