/**
 * Represents the smallest unit within a parsed text document
 */
@Suppress("MemberVisibilityCanBePrivate")
@JsExport
sealed class ParserItem<T> : TextWithRange, CaosItem {

    /**
     * The range of this parser item in the document
     */
    abstract override val textRange: RangeWithIndex

    /**
     * The interpreted value of its text in the document
     */
    @JsName("value")
    abstract val value: T

    /**
     * The base type as seen by the game engine
     */
    @JsName("actualType")
    abstract val actualType: Int

    /**
     * The item's type as seen from the Parser
     */
    @JsName("typeToken")
    abstract val typeToken: Int

    /**
     * The original text in the document
     */
    abstract override val text: String


    /**
     * The index of this or the last sub parser item in the containing parse result
     */

    @JsName("parserIndexEnd")
    open val parserIndexEnd: Int? get() = textRange.parserIndex

    /**
     * The index of this or the starting sub-parser-item in the parse result
     */

    @JsName("parserIndexStart")
    open val parserIndexStart: Int? get() = textRange.parserIndex

