    /**
     * A CAOS2Pray item which may be a tag (Agent Type = 1) or command (Link "./skeeter.cos")
     */
    @JsName("Caos2Comment")
    data class Caos2Comment(

        /**
         * The range of this parser item in the document
         */
        override val textRange: RangeWithIndex,

        /**
         * Raw text that makes up this parser element
         */
        override val text: String,


        /**
         * The tag or command token
         */
        @JsName("token")
        val token: TokenVal,

        /**
         * Values for the given command or tag
         */
        @JsName("values")
        val values: Array<ParserItem<*>>,

        @JsName("eq")
        val eq: TokenVal?,

        val caos2Hash: TokenVal?,
    ) : ParserItem<String>() {

        override val value get() = token.text

        /**
         * This item as a string
         */
        override fun toString(): String {
            val values = values.joinToString(" ") { if (it.value is Int) it.value.toString() else "\"${it.value}\"" }
            return if (isTag) {
                token.text + " = " + values
            } else {
                token.text + ' ' + values
            }
        }

        override val parserIndexEnd: Int? get() = values
            .lastOrNull()
            ?.textRange?.parserIndex
            ?: token.textRange.parserIndex

        override fun equals(other: Any?): Boolean {
            if (this === other) return true
            if (other !is Caos2Comment) return false

            if (textRange != other.textRange) return false
            if (text != other.text) return false
            if (token != other.token) return false
            if (!values.contentEquals(other.values)) return false
            if (eq != other.eq) return false
            if (typeToken != other.typeToken) return false
            if (actualType != other.actualType) return false
            if (isTag != other.isTag) return false

            return true
        }

        override fun hashCode(): Int {
            var result = textRange.hashCode()
            result = 31 * result + text.hashCode()
            result = 31 * result + token.hashCode()
            result = 31 * result + values.contentHashCode()
            result = 31 * result + (eq?.hashCode() ?: 0)
            result = 31 * result + typeToken
            result = 31 * result + actualType
            result = 31 * result + isTag.hashCode()
            return result
        }

        @JsName("valueAsStrings")
        val valuesAsStrings by lazy {
            values.map {
                it.text.stripSurroundingQuotes()
            }.toTypedArray()
        }

        /**
         * The item's type as seen from the Parser
         */
        override val typeToken = TypeTokens.CAOS2_COMMENT

        /**
         * The type as seen from the game engine
         */
        override val actualType: Int = ValueType.CAOS2_COMMENT.value

        @JsName("isTag")
        val isTag = eq != null

        /**
         * The tag key if this is a tag CAOS2Pray statement
         * Tags have an equal sign and can be multi-word, un-quoted or quoted
         */
        @JsName("tag")
        val tag get() = if (isTag) token.text else null

        /**
         * Command name if this is a CAOS2Pray command tag
         */
        @JsName("command")
        val command get() = if (!isTag) token.text else null

        /**
         * Int value, if value is unquoted int
         */
        @JsName("intValue")
        val intValue by lazy {
            if (values.size == 1) {
                (values.first() as? IntVal)?.value
            } else {
                null
            }
        }


        companion object {
            /**
             * Regex used to determine if the given CAOS2Pray comment is a tag or not
             */
            private val TAG_REGEX = "^\\s*([^=]*?\\s*)=\\s*([^\r\n]+)\\s*$".toRegex()
        }
    }

    /**
     * A single word token within the CAOS document. Its token value is an int for quick comparison
     */
    @JsName("CommandToken")
    data class CommandToken(

        /**
         * The range of this parser item in the document
         */
        override val textRange: RangeWithIndex,

        /**
         * The interpreted value of its text in the document
         */
        override val value: String,
    ) : ParserItem<String>() {
        /**
         * The type as seen from the game engine
         */
        override val actualType: Int
            get() = ValueType.COMMAND.value

        /**
         * This command word as a 32bit uint
         */
        val token: Int by lazy {
            token(value.lowercase())
        }

        /**
         * Raw text that makes up this parser element
         */
        override val text: String get() = value

        /**
         * The item's type as seen from the Parser
         */
        override val typeToken = TypeTokens.COMMAND_TOKEN
    }

    /**
     * A group of related word token within the CAOS document.
     * Though not strictly a single element, it was easier to use one here
     */
    @JsName("CompoundCommandToken")
    data class CompoundCommandToken(
        /**
         * Array of the words/tokens making up this command
         */
        private val mTokens: Array<CommandToken>
    ) : ParserItem<String>() {

        /**
         * The type as seen from the game engine
         */
        override val actualType: Int
            get() = ValueType.COMMAND.value

        /**
         * The list of command words/tokens sorted in order
         */
        val tokens: Array<CommandToken> by lazy {
            mTokens.sortedBy { (it.textRange.startIndex) }
                .toTypedArray()
        }

        /**
         * The range of this item within the document
         */
        override val textRange: RangeWithIndex by lazy {
            if (tokens.size == 1) {
                tokens.first().textRange
            }
            val first = tokens.first().textRange
            val last = tokens.last().textRange
            RangeWithIndexImpl(
                startIndex = first.startIndex,
                endIndex = last.endIndex,
                start = first.start,
                end = last.end,
                parserIndex = null
            )
        }

        override val parserIndexEnd: Int? get() =
            mTokens
            .lastOrNull()
            ?.textRange?.parserIndex
                ?: textRange.parserIndex

        /**
         * The interpreted value of this item, a single string of all word tokens
         */
        override val value: String by lazy {
            tokens.joinToString(" ") { it.text }
        }

        /**
         * Raw text that makes up this parser element
         */
        override val text: String get() = value


        /**
         * The item's type as seen from the Parser
         */
        override val typeToken = TypeTokens.COMMAND_TOKEN

        /**
         * Overridden equals to support array value
         */
        override fun equals(other: Any?): Boolean {
            if (this === other) return true
            if (other !is CompoundCommandToken) return false

            if (!mTokens.contentEquals(other.mTokens)) return false
            if (typeToken != other.typeToken) return false

            return true
        }

        /**
         * Overridden hashcode to support array
         */
        override fun hashCode(): Int {
            var result = mTokens.contentHashCode()
            result = 31 * result + typeToken
            return result
        }

        /**
         * A string representation of this parser item
         */
        override fun toString(): String {
            return value
        }
    }

