package com.bedalton.log.internal

import com.bedalton.log.ILoggerObject
import com.bedalton.log.LoggerColor

/**
 * A default logger implementation to use with the global Log object
 */
internal expect object DefaultLoggerObject: ILoggerObject {
	override fun log(replace:Boolean, message: String, color: LoggerColor?)

	override fun info(replace:Boolean, message: String, color: LoggerColor?)

	override fun warning(message: String, color: LoggerColor?)

	override fun error(message: String, color: LoggerColor?)

	override fun logMemory()

	override val prependLogType:Boolean

	override fun getColorPrefix(color: LoggerColor?): String?

}

val namespacePrefixRegex = "^%([^%]+)%(.*)$".toRegex()
internal fun String.stripNamespacePrefix(): String {
	return this.replace(namespacePrefixRegex, "$2")
}