package com.bedalton.common.util

import kotlin.collections.joinToString

fun <T> Collection<T>.joinToString(delimiter: Char, prefix: CharSequence = "", postfix: CharSequence = "", limit: Int = -1, truncated: CharSequence = "...",  transform: ((T) -> String)? = null): String {
    return this.joinToString("" + delimiter, prefix, postfix, limit, truncated, transform)
}

fun <T> Collection<T>.joinToStringWithPrefix(delimiter: Char, postfix: CharSequence = "", limit: Int = -1, truncated: CharSequence = "...",  transform: ((T) -> String)? = null): String {
    return this.joinToString("" + delimiter, "" + delimiter, postfix, limit, truncated, transform)
}

fun <T> Collection<T>.joinToStringWithPrefix(delimiter: String, postfix: CharSequence = "", limit: Int = -1, truncated: CharSequence = "...",  transform: ((T) -> String)? = null): String {
    return this.joinToString(delimiter, delimiter, postfix, limit, truncated, transform)
}