@file:Suppress("NON_EXPORTABLE_TYPE")

package com.bedalton.creatures.caos.server

import kotlin.js.JsExport

/**
 * Checks that a text range, contains a
 * @param range
 * @param lineNumber
 * @param column
 * @param ignoreColumn
 * @param soft allows some padding for in-range checks
 */
@JsExport
fun inRange(range: RangeWithIndex?, lineNumber: Int, column: Int, ignoreColumn: Boolean = false, soft: Boolean = true): Boolean {
    if (range == null) {
        throw Exception("TextRange is invalid in getRange")
    }
    val startLineNumber = range.start.line
    val endLineNumber = range.end.line
    val offsetColumn = column + 1

    return if (startLineNumber == endLineNumber) {
        if (lineNumber != startLineNumber) {
            return false
        }
        if (ignoreColumn) {
            return true
        }
        val mod = if (soft) 2 else 0
        column in (range.start.character - mod)..(range.end.character + mod)
    } else if (startLineNumber == lineNumber) {
        if (ignoreColumn) {
            return true
        }
        if (soft) {
            range.start.character - 2 <= offsetColumn
        } else {
            range.start.character <= offsetColumn
        }
    } else if (endLineNumber == lineNumber) {
        if (ignoreColumn) {
            return true
        }
        if (soft) {
            range.end.character + 2 >= offsetColumn
        } else {
            range.end.character >= offsetColumn
        }
    } else {
        lineNumber in (startLineNumber + 1) until endLineNumber
    }
}

/**
 * Checks if range contained in any other range, inclusive
 */
fun inRange(range: Range, ranges: Array<Range>): Boolean {
    return ranges.any { otherRange ->
        inRange(range, otherRange)
    }
}

/**
 * Get sort value as an int for a range object
 */
val Range.sortValue: Int get() {
    val startLine = start.line
    val startColumn = start.character
    return startLine shl 16 or startColumn
}

/**
 * Check if one range contains another
 */
fun RangeWithIndex.contains(otherRange: RangeWithIndex): Boolean {
    val oStart = startIndex
    val oEnd = endIndex
    val theRange = oStart..oEnd
    return otherRange.startIndex in theRange && otherRange.endIndex in theRange
}


/**
 * Check if a child range is completely enclosed in another range
 */
fun inRange(child: Range, parent: Range): Boolean {
    if (child.start.line < parent.start.line) {
        return false
    }
    val endLineNumber = child.end.line
    if (endLineNumber > parent.end.line) {
        return false
    }
    if (child.start.line == parent.start.line) {
        val startColumn = child.start.character
        if (startColumn < parent.start.character) {
            return false
        }
    }
    if (endLineNumber == parent.end.line) {
        val endColumn = child.end.character
        if (endColumn > parent.end.character) {
            return false
        }
    }
    return true
}