/**
 * Collects parser items in a CAOS file
 * @param lib CAOS definitions for a given CAOS variant
 * @param items a list of parsed tokens
 */
internal class CaosWalker(
    variant: String,
    private val lib: CaosLib,
    originalText: String,
    items: Array<ParserItem<*>>,
    private val checkCancelled: () -> Unit,
) {

    private val variant: String = variant.uppercase()
    private val caosVariant = CaosVariant.fromVal(variant).let {
        if (it == CaosVariant.UNKNOWN) {
            null
        } else {
            it
        }
    }
    private val mItems = items.filter { it !is WhitespaceItem }
    private val mWhitespaceItems = items.filterIsInstance<WhitespaceItem>()
    private val commandWalker by lazy {
        CommandWalker(
            lib,
            originalText,
            mItems.toTypedArray(),
            checkCancelled
        )
    } // Transforms values to parameter types as well
    val errors: Array<ErrorVal> by lazy { collectErrors().distinct().toTypedArray() }
    val commandCalls: Array<CommandCall> get() = commandWalker.commandCalls
    val looseTokens: Array<ParserItem<*>> get() = commandWalker.looseTokens
    val equalityStatements by lazy {
        commandWalker.equalityStatements
    }
    val equalityStatementRanges by lazy {
        commandWalker.equalityStatementRanges
    }
    val comments get() = commandWalker.comments
    val caos2Comments get() = commandWalker.caos2Comments

    private fun collectErrors(): List<ErrorVal> {
        val errors: MutableList<ErrorVal> = mutableListOf()
        try {
            errors.addAll(collectWhitespaceErrors())
            errors.addAll(collectTypeErrors())
            errors.addAll(collectIncompleteCommandErrors())
            errors.addAll(variantErrors())
            errors.addAll(commandWalker.looseTokens.map {
                if (it is ErrorVal) {
                    it
                } else if (it is CommandToken) {
                    if (it.value.length != 4 || CaosLibs.commands(intArrayOf(token(it.value)))?.first.isNullOrEmpty()) {
                        ErrorVal(
                            textRange = it.textRange,
                            message = "Invalid input '${it.value}'",
                            type = ErrorTypes.GENERAL,
                            text = it.text
                        )
                    } else {
                        ErrorVal(
                            textRange = it.textRange,
                            message = "Unexpected command token '${it.value}'",
                            type = ErrorTypes.GENERAL,
                            text = it.text
                        )
                    }
                } else {
                    ErrorVal(
                        textRange = it.textRange,
                        message = "Unexpected value '${it.value}'",
                        type = ErrorTypes.GENERAL,
                        text = it.text
                    )
                }
            })
        } catch (_: ParseCancelledException) {
        }
        return errors.sortedBy {
            it.textRange.startIndex
        }
    }

    private fun collectTypeErrors(): List<ErrorVal> {
        val errors: MutableList<ErrorVal> = mutableListOf()
        for (call in commandWalker.commandCalls) {
            checkCancelled()
            for (i in 0 until call.arguments.size) {
                val argument = call.arguments[i]
                val parameter = call.command.parameters.getOrNull(i)
                    ?: continue
                val parameterType = ValueType.fromIntValue(parameter.typeId)
                val argumentType = ValueType.fromIntValue(argument.type)
                if (parameterType like argumentType) {
                    continue
                }
                val error = ErrorVal(
                    argument.textRange,
                    message = ErrorFormatter.typeMismatchError(
                        call.command.command,
                        parameter,
                        actualType = argumentType.simpleName
                    ),
                    type = ErrorTypes.TYPE_ERROR,
                    text = argument.text
                )
                errors.add(error)
            }
        }
        return errors
    }

    private fun collectIncompleteCommandErrors(): List<ErrorVal> {
        val errors: MutableList<ErrorVal> = mutableListOf()
        for (call in commandWalker.commandCalls) {
            checkCancelled()
            if (call.arguments.size > call.command.parameters.size) {
                continue
            }
            if (!call.done) {
                if (call.missingParameters.size == 1 && call.command == ConditionCommand) {
                    continue
                }
                val range = if (call.arguments.isEmpty()) {
                    call.tokenTextRange.let { if (it.empty()) call.textRange else it }
                } else {
                    call.arguments.last().textRange.let { end ->
                        RangeWithIndexImpl(
                            startIndex = end.endIndex,
                            endIndex = end.endIndex,
                            start = end.end,
                            end = end.end
                        )
                    }
                }
                val missingParameterString =
                    call.missingParameters.joinToString { parameter -> "${parameter.name} (${parameter.typeName})" }
                val error = ErrorVal(
                    textRange = range,
                    message = "${call.command.command} is missing parameters [${missingParameterString}] (Index:${range.startIndex}, Line:${range.start.line},Column:${range.start.character})",
                    type = ErrorTypes.INCOMPLETE_COMMAND_ERROR,
                    text = call.text
                )
                errors.add(error)
            }
        }
        return errors
    }

    private fun collectWhitespaceErrors(): List<ErrorVal> {
        return if (caosVariant?.isOld == true) {
            annotateWhitespaceC1e()
        } else {
            annotateWhitespaceC2e()
        }
    }

    private fun annotateWhitespaceC1e(): List<ErrorVal> {
        val items = (this.mItems + this.mWhitespaceItems)
            .sortedBy { it.startIndex }
        val whitespacePositional = items
            .mapIndexedNotNull { i, item ->
                if (item is WhitespaceItem) {
                    Pair(i, item)
                } else {
                    null
                }
            }
        return whitespacePositional.mapNotNull { (i, item) ->
            annotateWhitespaceC1e(i, item, items)
        }
    }

    private fun annotateWhitespaceC1e(i: Int, item: WhitespaceItem, items: List<ParserItem<*>>): ErrorVal? {
        val before = if (i > 0) items[i - 1] else null
        val newlineBefore = before?.endLine.orElse(0) < item.startLine
        val after = if (i + 1 < items.size) items[i + 1] else null
        val newlineAfter = after?.endLine.orElse(item.endLine) > item.endLine
        return when {
            newlineAfter && item is Spaces -> ErrorVal(
                item.textRange,
                message = "Trailing whitespace is not allowed",
                type = ErrorTypes.WHITESPACE_ERROR,
                text = item.value
            )

            !newlineBefore && item is Spaces && item.value.length > 1 -> ErrorVal(
                item.textRange,
                message = "Only one space or comma allowed",
                type = ErrorTypes.WHITESPACE_ERROR,
                text = item.value
            )

            else -> null
        }
    }

    private fun annotateWhitespaceC2e(): List<ErrorVal> {
        return mWhitespaceItems
            .filterIsInstance<Spaces>()
            .flatMap map@{ item ->
                val startIndex = item.startIndex
                val startLine = item.startLine
                val startCharacter = item.startCharacter
                val text = item.value
                val annotate = { i: Int ->
                    annotateCommaC2e(i, startLine, startCharacter, startIndex, text[i])
                }
                (text.indices).mapNotNull(annotate)
            }
    }

    private fun annotateCommaC2e(i: Int, startLine: Int, startCharacter: Int, startIndex: Int, text: Char): ErrorVal? {
        if (text != ',') {
            return null
        }
        val startPosition = PositionImpl(
            line = startLine,
            character = startCharacter + i
        )
        val endPosition = PositionImpl(
            line = startLine,
            character = startCharacter + i + 1
        )
        val range = RangeWithIndexImpl(
            start = startPosition,
            end = endPosition,
            startIndex = startIndex + i,
            endIndex = startIndex + i + 1
        )
        return ErrorVal(
            textRange = range,
            message = "Commas are allowed in C1e variants only",
            type = ErrorTypes.WHITESPACE_ERROR,
            text = ","
        )
    }

    private fun variantErrors(): List<ErrorVal> {
        val errors: MutableList<ErrorVal> = mutableListOf()
        outOfVariantCommandErrors(errors)
        varErrors(errors)
        eqErrors(errors)
        variantStringErrors(errors)
        return errors
    }

    private fun outOfVariantCommandErrors(errors: MutableList<ErrorVal>) {
        val caos2FileRegex = "(pray|cob)\\s*-?(file)".toRegex(RegexOption.IGNORE_CASE)
        val isCaos2 = commandWalker.caos2Comments.any {
            caos2FileRegex.matches(it.command ?: it.tag ?: "")
        }
        val caos2ScriptDelimiters = "iscr|rscr".toRegex(RegexOption.IGNORE_CASE)
        for (call in commandWalker.commandCalls) {
            checkCancelled()
            if (call.inVariant) {
                continue
            }
            if (isCaos2 && caos2ScriptDelimiters.matches(call.command.command)) {
                continue
            }
            errors.add(
                ErrorVal(
                    textRange = call.tokenTextRange,
                    message = ErrorFormatter.outOfVariantError(
                        call.command.command,
                        ErrorFormatter.formatVariants(call.command.variants)
                    ),
                    type = ErrorTypes.OUT_OF_VARIANT,
                    call.text
                )
            )
        }
    }

    private fun variantStringErrors(errors: MutableList<ErrorVal>) {
        val isOldVariant = variant like "C1" || variant like "C2"
        val error = if (isOldVariant)
            "Quote strings are invalid in $variant"
        else
            "Bracket strings are invalid in CV+ variants"

        val badStrings = (if (isOldVariant) {
            mItems.filter { item ->
                checkCancelled()
                item.typeToken == TypeTokens.QUOTE_STRING
            }
        } else {
            mItems.filter { item ->
                checkCancelled()
                item.value != "" && item.typeToken == TypeTokens.BRACKET_STRING
            }
        }).map {
            ErrorVal(textRange = it.textRange, message = error, type = ErrorTypes.OUT_OF_VARIANT, text = it.text)
        }
        errors.addAll(badStrings)

        if (isOldVariant) {
            val stringInEqErrors = commandCalls
                .filter { command ->
                    checkCancelled()
                    command.command.command.lowercase() == EQ_COMMAND_TOKEN
                }
                .flatMap { command ->
                    command.arguments
                        .filter { argument ->
                            argument.type in stringLikeTypesAsInt
                        }
                }
                .map { argument ->
                    ErrorVal(
                        textRange = argument.textRange,
                        message = STRINGS_IN_EQ_ERROR,
                        type = ErrorTypes.OUT_OF_VARIANT,
                        text = argument.text
                    )
                }
            errors.addAll(stringInEqErrors)
        }
    }

    private fun varErrors(errors: MutableList<ErrorVal>) {
        val variables = mItems.filterIsInstance<IndexedVar>()
        val getError = when (variant) {
            "C1" -> VariableValidator.C1
            "C2" -> VariableValidator.C2
            else -> VariableValidator.C2e
        }
        for (variable in variables) {
            checkCancelled()
            val error = getError(variable.type, variable.index)
                ?: continue
            errors.add(
                ErrorVal(
                    textRange = variable.textRange,
                    message = error,
                    type = ErrorTypes.OUT_OF_VARIANT,
                    text = variable.text
                )
            )
        }
    }

    private fun eqErrors(errors: MutableList<ErrorVal>) {
        val eqOps = mItems.filterIsInstance<ParserItem.EqOp>()
        val validRegex = if (variant in listOf("C1", "C2"))
            "EQ|NE|GT|GE|LT|LE|BT|BF".toRegex(RegexOption.IGNORE_CASE)
        else
            "EQ|NE|GT|GE|LT|LE|(<=)|(>=)|(<>)|<|>|=".toRegex(RegexOption.IGNORE_CASE)
        for (op in eqOps) {
            checkCancelled()
            if (validRegex.matches(op.value))
                continue
            errors.add(
                ErrorVal(
                    op.textRange,
                    if (op.value == "!=") "Eq op '!=' is invalid. Use '<>' or 'ne' instead" else "EqOp '${op.value}' is invalid in $variant",
                    type = ErrorTypes.OUT_OF_VARIANT,
                    text = op.text
                )
            )
        }
        if (variant like "C1" || variant like "C2") {
            for (join in mItems.filterIsInstance<EqJoin>()) {
                errors.add(
                    ErrorVal(
                        textRange = join.textRange,
                        message = "Equality joins are only available in CV+",
                        type = ErrorTypes.OUT_OF_VARIANT,
                        text = join.text
                    )
                )
            }
        }
    }
}

internal fun CommonToken.toRange(
    offsetIndex: Int? = null,
    offsetLine: Int? = null,
    offsetColumn: Int? = null,
): RangeWithIndex {
    val startIndex = startIndex
    val startLine = line
    val startColumn = charPositionInLine
    val stopIndex = stopIndex
    val lines = text.orEmpty().split("\n")
    val endLine = startLine + lines.size - 1
    val stopColumn = if (lines.size > 1)
        lines.last().length
    else
        startColumn + text.orEmpty().length
    return RangeWithIndexImpl(
        startIndex = startIndex + (offsetIndex ?: 0),
        endIndex = stopIndex + (offsetIndex ?: 0),
        start = PositionImpl(
            line = startLine + (offsetLine ?: 0),
            character = startColumn + (offsetColumn ?: 0)
        ),
        end = PositionImpl(
            line = endLine + (offsetLine ?: 0),
            character = stopColumn + (if (startLine == endLine) (offsetColumn ?: 0) else 0)
        )
    )
}

private fun ParserRuleContext.toTokenVal() = TokenVal(
    RangeWithIndexImpl(start!!, stop!!),
    text
)

private val DOIF = intArrayOf(token("doif"))
private val ESCN = intArrayOf(token("escn"))
private val ENUM = intArrayOf(
    token("enum"),
    token("epas"),
    token("etch"),
    token("esee"),
    token("econ")
)
private val LOOP = intArrayOf(token("loop"))
private val SUBR = intArrayOf(token("subr"))
private val REPS = intArrayOf(token("reps"))


// Endings
private val ENDI = token("endi")
private val EVER = token("ever")
private val NEXT = token("next")
private val NSCN = token("nscn")
private val REPE = token("repe")
private val RETN = token("retn")
private val UNTL = token("untl")

private val C3DS = listOf("C3", "DS")


private infix fun ParserRuleContext.to(other: ParserRuleContext): IntRange {
    val commandStart = start!!.startIndex
    val commandEnd = other.stop!!.stopIndex
    return commandStart..commandEnd
}

private infix fun ParserRuleContext.until(other: ParserRuleContext): IntRange {
    val commandStart = start!!.startIndex
    val commandEnd = other.stop!!.stopIndex
    return commandStart until commandEnd
}

private infix fun Token.to(other: Token): IntRange {
    val commandStart = startIndex
    val commandEnd = other.stopIndex
    return commandStart..commandEnd
}


private infix fun Token.until(other: Token): IntRange {
    val commandStart = startIndex
    val commandEnd = other.stopIndex
    return commandStart until commandEnd
}

typealias VariableErrorGenerator = (group: String, index: Int) -> String?

private object VariableValidator {
    private val VARxError = ErrorFormatter.variableTypeError("VARx", ErrorFormatter.formatVariants(listOf("C1", "C2")))
    private val VAxxError =
        ErrorFormatter.variableTypeError("VAxx", ErrorFormatter.formatVariants(listOf("C2", "CV", "C3", "DS", "SM")))
    private val OVxxError =
        ErrorFormatter.variableTypeError("OVxx", ErrorFormatter.formatVariants(listOf("C2", "CV", "C3", "DS", "SM")))

    @Suppress("ConstPropertyName")
    private const val OBVxC1Error = "C1 supports only OBV0-OBV2 object variables"
    private val OBVxC2eError =
        ErrorFormatter.variableTypeError("OBVx", ErrorFormatter.formatVariants(listOf("C1", "C2")))
    private val MVxxError =
        ErrorFormatter.variableTypeError("MVxx", ErrorFormatter.formatVariants(listOf("CV", "C3", "DS", "SM")))

    val C1: VariableErrorGenerator = { group, index ->
        when (group) {
            "VARx" -> null
            "VAxx" -> VAxxError
            "OBVx" -> {
                if (index < 3)
                    null
                else
                    OBVxC1Error
            }

            "OVxx" -> OVxxError
            "MVxx" -> MVxxError
            else -> null
        }
    }
    val C2: VariableErrorGenerator = { group, _ ->
        when (group) {
            "MVxx" -> MVxxError
            else -> null
        }
    }
    val C2e: VariableErrorGenerator = { group, _ ->
        when (group) {
            "VARx" -> VARxError
            "OBVx" -> OBVxC2eError
            else -> null
        }
    }
}

private val stringLikeTypesAsInt: List<Int> = listOf(
    ValueType.STRING.value,
    ValueType.C1_STRING.value,
    ValueType.HEXADECIMAL.value,
    ValueType.BYTE_STRING.value,
    ValueType.ANIMATION.value
)


private const val STRINGS_IN_EQ_ERROR = "Strings in equality statement are allowed in CV+ variants only"

