package com.bedalton.creatures.caos.formatter

import com.bedalton.creatures.caos.collectors.*
import com.bedalton.creatures.caos.server.RangeImpl
import com.bedalton.creatures.caos.server.TextEditImpl
import com.bedalton.creatures.caos.server.contains
import com.bedalton.creatures.caos.server.inRange
import kotlin.math.max
import kotlin.math.min


/**
 * Formats a newline token, keeping it in the min/max range
 */
internal fun Formatter.formatNewLine(item: ParserItem.NewLine) {
    val lastWasComment = state.peak(-1) is ParserItem.Comment
    val newLines = newLineCountConstrained(item.lines, lastWasComment, lastWasComment && state.peak()?.isComment() == true)
    val newLineText = if (newLines > 0) {
        newLine.repeat(newLines)
    } else {
        " "
    }
    state.newlineLast = newLines > 0

    if (item.text != newLineText) {
        val range = RangeImpl(
            item.textRange.start,
            item.textRange.end
        )
        state.edits.add(
            TextEditImpl(
                range,
                newLineText
            )
        )
        val existingLineCount = item.text.count { it == '\n' }
        val newLineCount = newLineText.count {it == '\n' }
        if (existingLineCount == newLines) {
            state.editReasons.add(EditReason.SPACE_NEEDED)
        } else if (existingLineCount < newLineCount) {
            state.editReasons.add(EditReason.NEWLINES_NEEDED)
        } else {
            state.editReasons.add(EditReason.NEWLINES_TOO_MANY)
        }
    }
    state.out.append(newLineText)
}


/**
 * Formats a space token to the right length, or deleting as necessary
 */
internal fun Formatter.formatSpace(item: ParserItem.Spaces) {
    val lastItem = state.lastItem
    val nextItem = state.peak()
    if (lastItem == null || nextItem.isWhitespaceOrComment()) {
        if (nextItem !is ParserItem.Comment) {
            state.edits.add(
                TextEditImpl(
                    RangeImpl(
                        item.start,
                        item.end
                    ),
                    ""
                )
            )
            state.editReasons.add(EditReason.SPACE_TOO_MANY)
        }
        return
    }

    var space = when {
        lastItem is ParserItem.NewLine -> {
            state.currentTab
        }
        willNewlineNext(0) -> {
            state.currentTab
        }
        willNewlineNext(1) -> {
            ""
        }
        lastItem.endLine == item.startLine -> {
            " "
        }
        else -> {
            item.text
        }
    }
    if ((state.peak(1) as? ParserItem.CommandToken)?.token in state.waiting.firstOrNull().orEmpty()) {
        if (space.length >= state.tab.length) {
            space = space.substring(state.tab.length)
        }
    }
    if (item.text != space) {
        val difference = item.text.length - space.length
        if (difference == 0) {
            state.editReasons.add(EditReason.TAB_CHANGE)
        } else if (difference < 0) {
            state.editReasons.add(EditReason.SPACE_NEEDED)
        } else {
            state.editReasons.add(EditReason.SPACE_TOO_MANY)
        }
        state.edits.add(
            TextEditImpl(
                RangeImpl(
                    item.start,
                    item.end
                ),
                space
            )
        )
    }
    state.out.append(space)
}


private fun Formatter.willNewlineNext(offset: Int = 0): Boolean {
    // IF commands are allowed to be on the same line, return
    if (state.keepSameLine) {
        return false
    }
    val item = state.peak(offset)
        ?: return false

    val next = state.peak(offset + 1)

    // If this item is a comment, let it handle its own new lines
    if (item.isComment() || item is ParserItem.NewLine || next is ParserItem.NewLine) {
        return false
    }

    val last = state.peak(-1)

    if (last != null) {
        val eqStatement = state.equalityStatementRanges.firstOrNull {
            it.contains(last.textRange)
        }
        if (eqStatement != null) {
            return !eqStatement.contains(item.textRange)
        }
    }

    // Check if this command is actually part of a new block level command
    val currentCommand = state.blockLevelCommandCalls.firstOrNull()
    return (currentCommand == null || !currentCommand.contains(item.textRange.startIndex))
}

/**
 * Insert a new line if needed between command calls
 */
internal fun Formatter.addNewLineIf(item: ParserItem<*>) {
    val willNewlineNext = willNewlineNext(0)
    if (item.textRange.startIndex > (state.blockLevelCommandCalls.firstOrNull()?.endInclusive ?: Int.MAX_VALUE)) {
        state.blockLevelCommandCalls.removeAt(0)
    }
    if (!willNewlineNext) {
        return
    }
    val itemRange = item.textRange
    if (item is ParserItem.EqJoin || state.peak(-1) is ParserItem.EqJoin || state.equalityStatements.any { it.textRange.contains(itemRange) }) {
        return
    }

    var i = -1
    while (state.peak(i)?.isWhitespace() == true) {
        if (state.peak(i) is ParserItem.NewLine) {
            return
        }
        --i
    }

    val newLine = state.newLines
    val space = newLineSpace(item)
    val final = newLine + space
    state.out.append(final)
    state.edits.add(
        TextEditImpl(
            range = RangeImpl(
                item.start,
                item.start
            ),
            newText = final
        )
    )
    state.editReasons.add(EditReason.NEWLINES_NEEDED)
}

private fun Formatter.newLineSpace(item: ParserItem<*>): String {
    if (state.peak()?.isWhitespace() != false && !willNewlineNext()) {
        return ""
    }
    return when (item) {
        is ParserItem.Spaces -> {
            ""
        }
        is ParserItem.Comment -> {
            if (state.indentComments) {
                state.currentTab
            } else {
                ""
            }
        }
        is ParserItem.Caos2Comment -> ""
        is ParserItem.NewLine -> ""
        is ParserItem.CommandToken -> {
            if (item.token in state.waiting.getOrNull(0).orEmpty()) {
                state.currentTab.substring(state.tab.length)
            } else {
                state.currentTab
            }
        }
        else -> state.currentTab
    }
}

/**
 * Ensures there is a proceeding space if needed between non-whitespace tokens
 */
internal fun Formatter.ensureSpace(item: ParserItem<*>) {
    if (state.lastItem?.isComment() == true) {
        return
    }
    if (
        !item.isWhitespaceOrComment() &&
        state.peak(-1)?.let { it.isComment() || it is ParserItem.Spaces } != true
    ) {

        val space = state.currentTab
        state.edits.add(
            TextEditImpl(
                RangeImpl(
                    item.start,
                    item.start
                ),
                space
            )
        )
        state.editReasons.add(EditReason.SPACE_NEEDED)
        state.out.append(space)
    }
}


/**
 * Compute how many continuation indents are needed for the item at this line
 * Continuation indents occur when a command and its arguments span multiple lines
 * NOTE: Computes continuation indents only, not regular indents.
 * Regular indents still need to be added to it
 */
internal fun computeContinuationsForFormatter(state: FormatterState, item: ParserItem<*>): Int {
    val line = item.startLine
    val character = item.startCharacter + 1
    val startIndex = item.startIndex
    val startLine = item.startLine
    var indents = 0
    state.equalityStatementGroups.firstOrNull {
        inRange(it.first, startLine, character)
    }?.let { (_, statements) ->
        var last: EqualityStatement?
        var lastLine = -1
        for (i in statements.indices) {
            last = statements[i]
            if (last.startIndex > startIndex) {
                break
            }
            if (lastLine != last.startLine) {
                indents++
            }
            lastLine = last.endLine
        }
    }

    val enclosingCommands = state.allCommands.filter { inRange(it.textRange, line, character) }
    var lastLine = enclosingCommands.firstOrNull()?.startLine
        ?: return indents
    var ensureOne = false
    for (command in enclosingCommands.drop(1)) {
        if (lastLine != command.startLine) {
            indents++
            lastLine = command.startLine
        } else if (item.endIndex == command.endIndex && command.startLine != command.endLine) {
            ensureOne = true
        }
    }
    if (enclosingCommands.lastOrNull()?.startLine != startLine) {
        indents = min((enclosingCommands.maxOfOrNull { it.endLine } ?: 0) - (enclosingCommands.minOfOrNull { it.startLine } ?: 0), ++indents)
    }
    val commandRange = enclosingCommands.firstOrNull()?.textRange
    if (indents == 0) {
        if (ensureOne) {
            indents = 1
        } else if (
            commandRange != null && commandRange.start.line != startLine
        ) {
            indents = 1
        } else if (commandRange != null && item.endIndex == commandRange.endIndex && commandRange.start.line != commandRange.end.line) {
            indents = 1
        }
    }
    return indents
}

internal fun Formatter.newLineCountConstrained(lines: Int, commentLast: Boolean, commentNext: Boolean): Int {
    if (commentNext) {
        return min(lines, max(state.maxBlankLines, 1))
    }
    val temp = if (lines - 1 > state.maxBlankLines) {
        state.maxBlankLines + 1
    } else if (state.forceMinBlankLinesAfterComments || !commentLast) {
        min(state.maxBlankLines + 1, max(state.minBlankLines + 1, lines))
    } else {
        min(state.maxBlankLines + 1, lines)
    }
    return max(1, temp)
}


internal fun String.showWhitespace(): String {
    return this
        .replace("\\r\\n", "[\\n]")
        .replace("\r", "")
        .replace("\n", "[\\n]")
        .replace("\t", "[\\t]")
        .replace(" ", "[ ]")
}