    /**
     * Hint for showing a bit flags values for an argument
     * ie attr 3 (carryable, mouseable)
     */
    ATTRIBUTE_BITFLAGS_ARGUMENT_HINT("parameterBitFlagValues", "Show bit flag for argument value", 100) {
        override fun isApplicable(variant: GameVariant, element: Pair<CommandCall, Argument>): Boolean {
            if ((element.second.parserItem as? IntVal)?.value.orElse(0) < 1) {
                return false
            }
            return usesBitFlags(variant, element)
        }

        private fun usesBitFlags(variant: GameVariant, element: Pair<CommandCall, Argument>): Boolean {
            return getValuesList(variant, element)?.bitflag ?: false
        }

        override fun provideHints(variant: CaosVariant, element: Pair<CommandCall, Argument>): List<InlayHint> {
            // Get bit flag int value if any
            val bitFlagValue = (element.second.parserItem as? IntVal)?.value
                ?: return EMPTY_INLAY_LIST

            // If value is not greater than 0, then it does not matter if it is bitflags or not
            if (bitFlagValue < 1)
                return EMPTY_INLAY_LIST

            // Get values list
            val valuesList = getValuesList(variant, element)
                ?: return EMPTY_INLAY_LIST

            // Get end position if possible
            val position = element.second.end()
            return getBitFlagHintValues(valuesList, bitFlagValue, position)
        }

