    // Gets simple name for a family genus combination
    // i.e. scrp 2 8 (vendor) ...
    ASSUMED_GENUS_NAME_HINT("assumedGenusName", "Show genus simple name",102) {
        override fun isApplicable(variant: GameVariant, element: Pair<CommandCall, Argument>): Boolean {

            // Make sure this element is an int
            if (element.second.parserItem !is IntVal) {
                return false
            }

            // Get index for argument in command call
            val index = element.second.index
            if (index == null || index < 1) // Cannot have preceding FAMILY value if index is 0
                return false

            // Make sure family argument is an int value
            if (element.first.arguments.getOrNull(index - 1)?.parserItem !is IntVal) {
                return false
            }

            // Only need to show genus names for command arguments
            val commandDefinition = element.first.command

            // Find parameters in command
            val parameters = commandDefinition.parameters

            // Ensure this parameter is for argument defined as genus
            val thisParameter = parameters.getOrNull(index) ?: return false
            if (thisParameter.name notLike "genus") {
                return false
            }

            // Ensure previous parameter is labeled as family
            // Cannot suggest genus without family
            val previousParameter = parameters.getOrNull(index - 1)
                ?: return false
            return previousParameter.name like "family"
        }

//        override fun getHintInfo(element: Pair<CommandCall, Argument>): HintInfo {
//            return HintInfo.MethodInfo("Genus", listOf("family", "genus"), CaosScriptLanguage)
//        }

        override fun provideHints(variant: GameVariant, element: Pair<CommandCall, Argument>): List<InlayHint> {
            val genus = element.second.text.toIntOrNull()
                ?: return EMPTY_INLAY_LIST
            val familyIndex = element.second.parameter?.index?.let { it - 1}
                ?: return EMPTY_INLAY_LIST
            val family = element.first.arguments
                .getOrNull(familyIndex)
                ?.text
                ?.toIntOrNull()
                ?: return EMPTY_INLAY_LIST
            return getGenusInlayHint(variant, element, family, genus)
        }

        /**
         * Gets the actual inlay information for this family genus combination
         */
        private fun getGenusInlayHint(
            variant: GameVariant,
            element: Pair<CommandCall, Argument>,
            family: Int,
            genus: Int
        ): List<InlayHint> {
            val position = element.second.end()
            val genusName = getGenusName(variant, family, genus)
                ?: return EMPTY_INLAY_LIST
            return listOf(InlayHintImpl(position, "($genusName)", InlayKind.Type))
        }
    },

