        /**
         * Determines whether to show this parameter hint of not
         */
        override fun isApplicable(variant: GameVariant, element: Pair<CommandCall, Argument>): Boolean {
            return element.second is CommandCall &&
                    element.first.type != ValueType.CONDITION.value &&
                    !element.first.inEqualityExpression &&
                    !element.second.inEqualityExpression &&
                    element.second.type != ValueType.CONDITION.value
        }

        /**
         * Provide hints for this command's return type
         */
        override fun provideHints(variant: GameVariant, element: Pair<CommandCall, Argument>): List<InlayHint> {
            val commandElement = element.second as? CommandCall
                ?: return EMPTY_INLAY_LIST

            val command = commandElement.command

            var thisReturnTypeName: String = command.returnTypeName

            val thisParameter = commandElement.parameter
                ?: return EMPTY_INLAY_LIST

            val position = (element.second as? CommandCall)?.tokenTextRange?.end
                ?: return EMPTY_INLAY_LIST

            // In case parameter is Agent and return type is agent
            if (thisParameter.name == thisReturnTypeName) {
                return EMPTY_INLAY_LIST
            }


            // In C1/C2 agent return values are integers
            // and can be used anywhere integers are
            val isIntToAgentCoercion = variant.isOld
                    && command.returnTypeId == ValueType.AGENT.value
                    && thisParameter.typeId == ValueType.INT.value
            // When coercing an agent to an int
            // change the return value hint to depict that
            if (isIntToAgentCoercion) {
                thisReturnTypeName = "Agent->ID"
            }

            return listOf(InlayHintImpl(position, "(${thisReturnTypeName})"))


        }
