/**
 * Generates the inlay hints for a bitflag and bitflag list
 */
internal fun getBitFlagHintValues(typeList: CaosValuesList, bitFlagValue: Int, offset: Position): List<InlayHint> {
    val text = getBitFlagText(typeList, bitFlagValue, ",")
        ?: return EMPTY_INLAY_LIST
    return listOf(InlayHintImpl(offset, "($text)", InlayKind.Type))
}

internal fun getBitFlagText(typeList: CaosValuesList, bitFlagValue: Int, delimiter: String): String? {
    // This hint is only worried about bitflags
    // Return if not bit-flags, even if list exists, but is not Bit-Flags
    if (!typeList.bitflag) {
        return null
    }

    // Loop through bitflags values list, and collect matches to rvalue int value
    val values = mutableListOf<String>()
    val stripSuffers = if (typeList.name.lowercase().startsWith("attr")) {
        val regex = "^suffers?\\s+".toRegex(RegexOption.IGNORE_CASE);
        { name: String ->
            if (name.lowercase().startsWith("suffer")) {
                name.replace(regex, "")
            } else {
                name
            }
        }
    } else {
        { name: String ->
            name
        }
    }
    for (typeListValue in typeList.values) {
        try {
            val typeListValueValue = typeListValue.intValue
                ?: continue
            if (bitFlagValue and typeListValueValue > 0) {
                val name = stripSuffers(typeListValue.name)
                values.add(name)
            }
        } catch (_: Exception) {
        }
    }
    return values.filterNotNull().joinToString(delimiter)
}

/**
 * Gets the values list given an element
 */
internal fun getValuesList(variant: GameVariant, element: Pair<CommandCall, Argument>): CaosValuesList? {
    // Get values list for expression
    // If is SETV expression get values list for lvalue
    val (parent, argument) = element
    val valuesList: CaosValuesList? = if (parent.commandString likeAny setLike) {
        val leftValueIndex = parent.command.parameters.indexOfFirst { it.typeId == ValueType.VARIABLE.value }
        if (leftValueIndex < 0) {
            return null
        }
        val leftArg = parent.arguments.getOrNull(leftValueIndex)
        (leftArg  as? CommandCall)
            ?.command?.returnValuesList(variant.code)
            ?: leftArg?.parameter?.valuesList
    } else {
        argument.parameter?.valuesList
    }
    return valuesList
}

internal fun getC1ClasText(variant: GameVariant, element: Argument): String? {
    val clasValue = element.text.toIntOrNull()
        ?: return null
    val agentClass = AgentClassUtils.parseClas(clasValue)
        ?: return null
    val genusString = getGenusName(variant, agentClass.family, agentClass.genus)
        ?.let {
            "($it)"
        }
        ?: ""
    return "family:${agentClass.family} genus:${agentClass.genus}$genusString species:${agentClass.species}"
}

/**
 * Gets the actual inlay information for this family genus combination
 */
private fun getGenusName(
    variant: GameVariant,
    family: Int,
    genus: Int
): String? {
    val valuesList: CaosValuesList = CaosLibs[variant].valuesList("Genus")
    // If not value found, return empty inlay hints array
        ?: return null
    val valuesListValue = valuesList["$family $genus"]
        ?: return null
    // Format inlay hint for genus
    return valuesListValue.name
}