package com.bedalton.common.util

import kotlin.contracts.ExperimentalContracts
import kotlin.contracts.contract

private val REGEX_ESCAPES_REGEX = "\\\\([?$\\[\\]^.\\\\*(){}])".toRegex()

/**
 * Gets the string value (stripping escapes) for an item without surrounding quotes (single or double)
 *
 */
fun String.stringValue(trim: Int = 1, stripExtraBackslashes: Boolean = true): String {

    // Trim leading and trailing whitespace
    var string = if (trim > 0) this.trim() else this

    // Trim off single or double quotes as needed
    if (string.startsWith('"') && string.endsWith('"'))
        string = string.substring(1, string.lastIndex)
    else if (string.startsWith('\'') && string.endsWith('\''))
        string = string.substring(1, string.lastIndex)

    // Used to replace slash escapes
    // before removing unrecognized escapes
    @Suppress("SpellCheckingInspection")
    // Replaces escaped slashes with placeholder, so they are not stripped later
    var slashReplace = "xX==;::REPLACE_SLASHY::;==xX"
    if (string.contains(slashReplace)) {
        while (string.contains(slashReplace)) {
            slashReplace = "X:x${slashReplace}x:X"
        }
    }
    // Replace escape sequences
    return string
        // Un-escape known escape sequences
        .replace("\\\\", slashReplace)
        .replace("\\'", "'")
        .replace("\\r", "\r")
        .replace("\\b", "\b")
        .replace("\\n", "\n")
        .replace("\\\"", "\"")
        .replace("\\t", "\t")
        .replace("\\ ", " ")

        // Prevent escaping of regex escapes
        .replace(REGEX_ESCAPES_REGEX, "\\$1")

        // Replace extra backslashes if requested
        .replace("\\", if (stripExtraBackslashes) "" else "\\")

        // Replace backslash escape sequence with an actual backslash
        .replace(slashReplace, "\\").let {
            // Trim one more time if requested
            if (trim > 1)
                it.trim()
            else
                it
        }
}

/**
 * Checks if string is like the other, case-insensitive
 */
infix fun String?.like(other: String?): Boolean = this?.equals(other, true) ?: false

/**
 * Checks if string is NOT like the other, case-insensitive
 */
infix fun String?.notLike(other: String?): Boolean = this?.equals(other, true) != true

/**
 * Case-insensitive check if this string equals another in the list
 */
infix fun String?.like(others: Array<String>): Boolean {
    if (this == null) {
        return false
    }
    return others.toSet().any { other ->
        other.equals(this, true)
    }
}

/**
 * Case-insensitive check if the string is NOT equal to another in the array
 */
infix fun String?.notLike(others: Array<String>): Boolean {
    if (this == null) {
        return false
    }
    return others.toSet().any { other ->
        other.equals(this, true)
    }
}

/**
 * Case-insensitive check if the string equals another in the list
 */
infix fun String?.like(others: Collection<String>): Boolean {
    if (this == null) {
        return false
    }
    val set: Set<String> = if (others is Set<*>) {
        others as Set<String>
    } else {
        others.toSet()
    }
    return set.any { other ->
        other.equals(this, true)
    }
}

/**
 * Case-insensitive check if the string is NOT equal to another in the list
 */
infix fun String?.notLike(others: Collection<String>): Boolean {
    if (this == null) {
        return false
    }
    val set: Set<String> = if (others is Set<*>) {
        others as Set<String>
    } else {
        others.toSet()
    }
    return set.any { other ->
        other.equals(this, true)
    }
}


fun formatByteSize(size: Int): String {
    val length = size.toString().length
    return when {
        length > 9 -> {
            (size / 1_000_000_000.0).toFixed(2) + "TB"
        }

        length > 6 -> {
            (size / 1_000_000.0).toFixed(2) + "MB"
        }

        length > 3 -> {
            (size / 1_000.0).toFixed(2) + "KB"
        }

        else -> "${size}B"
    }
}

/**
 * Returns null if the string is empty or whitespace, otherwise original string is returned
 */
fun String?.nullIfEmpty(): String? {
    return if (this.isNullOrBlank())
        null
    else
        this
}


/**
 * Removes single or double quotes wrapping a string,
 * optionally unescaping the string
 */
fun String.stripSurroundingQuotes(superUnescape: Boolean): String {
    return stripSurroundingQuotes(null, superUnescape)
}
/**
 * Removes single or double quotes wrapping a string,
 * optionally unescaping the string
 * @param superUnescape [default: true]
 */
fun String.stripSurroundingQuotes(trim: Int? = null, superUnescape: Boolean? = null): String {
    val trimNotNull = trim ?: 1
    if (isEmpty()) {
        return ""
    }
    var string = if (trimNotNull > 0) this.trim() else this

    if (string.length == 1) {
        return if (string[0] == '"' || string[0] == '\'') {
            ""
        } else {
            this
        }
    }

    // Trim off whitespace and quotes as needed
    if (string.startsWith('"') && string.endsWith('"')) {
        string = string.substring(1, string.lastIndex)
    } else if (string.startsWith('\'') && string.endsWith('\'')) {
        string = string.substring(1, string.lastIndex)
    }
    if (superUnescape != false) {
        string = superUnescape(string)
    }
    return if (trimNotNull > 1)
        string.trim()
    else
        string
}

/**
 * Simple method to ensure a string ends with a given char
 * Created simply to ensure path ends with slash or backslash
 */
fun String.ensureStartsWith(char: Char): String {
    if (this.startsWith(char)) {
        return this
    }
    return char + this
}

/**
 * Simple method to ensure one string ends with a given text
 */
fun String.ensureStartsWith(tail: String): String {
    if (this.startsWith(tail)) {
        return this
    }
    return tail + this
}


/**
 * Simple method to ensure a string ends with a given char
 * Created simply to ensure path ends with slash or backslash
 */
fun String.ensureEndsWith(char: Char): String {
    if (this.endsWith(char)) {
        return this
    }
    return this + char
}

/**
 * Simple method to ensure one string ends with a given text
 */
fun String.ensureEndsWith(tail: String): String {
    if (this.endsWith(tail)) {
        return this
    }
    return this + tail
}


fun String.ensureNotEndsWith(tail: Char): String {
    return if (this.isEmpty() || this[0] == tail) {
        ""
    } else if (this.endsWith(tail)) {
        this.substring(0, this.lastIndex - 1)
    } else {
        this
    }
}

fun String.ensureNotEndsWith(tail: String): String {
    return if (this.isEmpty() || this == tail) {
        ""
    } else if (this.endsWith(tail)) {
        this.substring(0, this.lastIndex - tail.length + 1)
    } else {
        this
    }
}

fun String.ensureNotStartsWith(prefix: Char): String {
    return if (this.isEmpty() || this[0] == prefix) {
        ""
    } else if (this.startsWith(prefix)) {
        this.substring(1)
    } else {
        this
    }
}


fun String.ensureNotStartsWith(prefix: String): String {
    return if (this.isEmpty() || this == prefix) {
        ""
    } else if (this.startsWith(prefix)) {
        this.substring(prefix.length)
    } else {
        this
    }
}


fun String.charCodeAt(i: Int): Int {
    return this[i].code
}

@OptIn(ExperimentalContracts::class)
fun String?.isNotNullOrEmpty(): Boolean {
    contract {
        returns(true) implies (this@isNotNullOrEmpty != null)
    }
    return this != null && this.isNotEmpty()
}

fun String?.isNotNullOrBlank(): Boolean {
    contract {
        returns(true) implies (this@isNotNullOrBlank != null)
    }
    return !this.isNullOrBlank()
}

fun String.count(substring: String, ignoreCase: Boolean = false): Int {
    var out = 0
    var index = 0
    val thisLength = length
    val substringLength = substring.length
    while (index < thisLength) {
        index = this.indexOf(substring, index, ignoreCase)
        if (index < 0) {
            break
        }
        out++
        index += substringLength
    }
    return out
}

fun StringBuilder.quote(item: Any): StringBuilder {
    return append("\"").append(superEscape(item.toString())).append("\"")
}

internal val NEWLINE_REGEX = "\r?\n".toRegex()
private const val ESCAPE_SEQUENCE = ";;#@(_x.x_)@#;;"


/**
 * Strip escape sequences from a string
 */
fun superUnescape(string: String): String {
    // ensure that escape sequence is not found in string first
    var escape = ESCAPE_SEQUENCE
    while (string.contains(escape)) {
        escape = "!x($escape)x!"
    }
    val tail = if (string.endsWith("\\")) "\\" else ""
    return string.replace("\\\\", escape)
        .replace("\\n", "\n")
        .replace("\\r", "\r")
        .replace("\\\"", "\"")
        .replace("\\'", "'")
        .replace("\\t", "\t")
        .replace("\\b", "\b")
        .replace("\\ ", " ")
        // Prevent escaping of regex escapes
        .replace(REGEX_ESCAPES_REGEX, "\\$1")
//        .replace("\\", "") // remove useless escape
        .replace(escape, "\\")
        .replace(NEWLINE_REGEX, "\r\n") + tail
}

/**
 * Strip escape sequences for the given escape characters
 */
fun String.superUnescape(vararg chars: Char): String {
    // ensure that escape sequence is not found in string first
    var escape = ESCAPE_SEQUENCE
    while (this.contains(escape)) {
        escape = "!x($escape)x!"
    }

    // Get potential tail
//    val tail = if (string.endsWith("\\")) "\\" else ""
    var escaped = this.replace("\\\\", escape)

    if ('\n' in chars || 'n' in chars) {
        escaped = escaped.replace("\\n", "\n")
    }

    if ('\r' in chars || 'r' in chars) {
        escaped = escaped.replace("\\r", "\r")
    }

    if ('"' in chars) {
        escaped = escaped.replace("\\\"", "\"")
    }

    if ('\'' in chars) {
        escaped = escaped.replace("\\'", "'")
    }

    if ('\t' in chars || 't' in chars) {
        escaped = escaped.replace("\\t", "\t")
    }

    if ('\b' in chars || 'b' in chars) {
        escaped = escaped.replace("\\b", "\b")
    }

    if (' ' in chars) {
        escaped = escaped.replace("\\ ", " ")
    }

    for (char in chars.filterNot { it in listOf('\n', '\r', '"', '\'', '\t', '\b', ' ') }) {
        escaped = escaped.replace("\\$char", "$char")
    }

    return escaped
        .replace(escape, if (chars.contains('\\')) "\\" else "\\\\")
//        .replace(NEWLINE_REGEX, "\r\n") + tail // REMOVED: as trailing slash should not have been removed
//        .replace(NEWLINE_REGEX, "\r\n") // REMOVED: Do not assume needs \r\n
}

/**
 * Escape known escape sequence characters
 */
fun superEscape(string: String): String {
    // ensure that escape sequence is not found in string first
    var escape = ESCAPE_SEQUENCE
    while (string.contains(escape)) {
        escape = "!x($escape)x!"
    }
    return string.replace("\\", escape)
        .replace("\n", "\\n")
        .replace("\r", "\\r")
        .replace("\"", "\\\"")
        .replace("'", "\\'")
        .replace("\t", "\\t")
        .replace("\b", "\\b")
        .replace(escape, "\\\\")
}


@Suppress("SpellCheckingInspection")
private val allchars = "abcdefghijklmnopqrstuvwxyz0123456789".toCharArray()


/**
 * Generate a non-crypographically secure random string
 */
fun randomString(length: Int): String {
    return (0 until length).map { allchars.random() }
        .toCharArray()
        .concatToString()
}

fun String.capitalize(): String {
    return replaceFirstChar { if (it.isLowerCase()) it.uppercase() else it.toString() }
}

fun String.decapitalize(): String {
    return replaceFirstChar { if (it.isUpperCase()) it.lowercase() else it.toString() }
}