package com.bedalton.common

import com.bedalton.log.LOG_DEBUG
import com.bedalton.log.Log
import com.bedalton.log.wIf
import org.w3c.dom.ImageBitmap
import org.w3c.dom.ImageBitmapSource
import org.w3c.fetch.Request
import org.w3c.fetch.RequestInit
import org.w3c.fetch.Response
import org.w3c.performance.Performance
import org.w3c.workers.CacheStorage
import kotlin.js.Promise

val self: Self get() {
    if (js("typeof self != 'undefined'") as Boolean) {
        return js("self").unsafeCast<Self>()
    }
    return if (js("typeof global == 'object'") as Boolean) {
        js("global.self = global")
        js("global.self").unsafeCast<Self>()
    } else if (js("typeof window != 'undefined'") as Boolean) {
        js("window").unsafeCast<Self>()
    } else {
        Log.wIf(LOG_DEBUG) { "Self is not defined and not in node scope" }
        throw NullPointerException("self is not defined in JS context")
    }
}

external interface Self {

    val caches: CacheStorage

//  val crypto: Crypto

//  val indexedDB: IDBFactory

    val origin: String

    val performance: Performance

    fun atob(data: String): String

    fun btoa(data: String): String

    val data: String

    fun clearInterval(handle: Number? = definedExternally)

    fun clearTimeout(handle: Number? = definedExternally)

    fun createImageBitmap(image: ImageBitmapSource): Promise<ImageBitmap>

    fun createImageBitmap(
        image: ImageBitmapSource,
        sx: Number,
        sy: Number,
        sw: Number,
        sh: Number
    ): Promise<ImageBitmap>

    val image: ImageBitmapSource

    fun fetch(input: Request, init: RequestInit? = definedExternally): Promise<Response>

    fun fetch(input: String, init: RequestInit? = definedExternally): Promise<Response>

    fun queueMicrotask(callback: dynamic)

    fun setInterval(handler: String, timeout: Number? = definedExternally, vararg arguments: dynamic): Number

    fun setInterval(handler: dynamic, timeout: Number? = definedExternally, vararg arguments: dynamic): Number

    fun setTimeout(handler: String, timeout: Number? = definedExternally, vararg arguments: dynamic): Number

    fun setTimeout(handler: dynamic, timeout: Number? = definedExternally, vararg arguments: dynamic): Number
}
