package com.bedalton.creatures.caos.formatter

import com.bedalton.creatures.caos.collectors.*
import com.bedalton.creatures.caos.exceptions.CaosException
import com.bedalton.creatures.caos.libs.ErrorTypes
import com.bedalton.creatures.caos.server.RangeImpl
import com.bedalton.creatures.caos.server.TextEditImpl
import com.bedalton.creatures.caos.utils.Log
import com.bedalton.creatures.caos.utils.token
import kotlin.js.JsExport

/**
 * Formats a CAOS document using variant and options
 */
@JsExport
fun format(variant: String, text: String, options: CaosFormatterOptions? = null): FormatResult {
    return Formatter.format(variant, text, options)
}

/**
 * Formatter object for a CAOS string
 */
internal class Formatter private constructor(
    private val variant: String,
    opts: CaosFormatterOptions?,
) {

    lateinit var state: FormatterState

    internal val newLine: String get() = state.newLineChar

    private val opts: CaosFormatterOptionsImpl = CaosFormatterOptionsImpl(variant, opts)

    /**
     * Formats a CAOS document string with consistent indents
     */
    private fun format(text: String): FormatResult {
        val result = parseCaos(variant, text)
        val nonWhitespaceErrors = result.errors
            .filter { it.type != ErrorTypes.WHITESPACE_ERROR && it.type != ErrorTypes.TOO_MANY_NEWLINES }
        if (nonWhitespaceErrors.isNotEmpty()) {
            throw FormatExceptionWithCaosErrors("Cannot format CAOS code with known errors", result.errors)
        }
        state = FormatterState(opts, result, getWhitespace(text).toList())

        if (result.items.size > 1 && state.whiteSpaceItems.isEmpty()) {
            Log.warn(TAG, "No whitespace found between items. Text: <${text}>")
        }
        loop()
        return FormatResult(state.formatted(), text, state.edits.toTypedArray(), state.editReasons.toTypedArray())
    }

    private fun loop() {
        // Loop through items in script
        while (state.hasNext) {
            val item = state.next()
                ?: return

            // If this is a new line, compute the continuation indents if any
            if (item.startLine > state.lastLine) {
                // These indent lines a bit more if the newlines exist within a parent command
                state.continuations = computeContinuationsForFormatter(state, item)

            }
            addNewLineIf(item)
            // Format item
            formatItem(item)
            if (state.continuations == 0) {
                state.eqIndents = 0
            }
            state.lastLine = item.endLine
        }
    }


    /**
     * Formats a parser item by type
     */
    private fun formatItem(item: ParserItem<*>) {
        when (item) {
            is ParserItem.Spaces -> {
                formatSpace(item)
            }
            is ParserItem.NewLine -> {
                formatNewLine(item)
            }
            is ParserItem.IndexedVar -> {
                formatIndexedVariable(item)
                state.newlineLast = false
            }
            is ParserItem.CommandToken -> {
                formatCommandToken(item)
                state.newlineLast = false
            }
            is ParserItem.CompoundCommandToken -> {
                formatCommandToken(item)
                state.newlineLast = false
            }
            is ParserItem.ByteStringVal -> {
                formatByteString(item)
                state.newlineLast = false
            }

            is ParserItem.Comment -> {
                formatComment(item)
                state.newlineLast = false
            }

            is ParserItem.Caos2Comment -> {
                formatCaos2(item)
                state.newlineLast = false
            }

            // Make sure to indent within a doif condition
            is ParserItem.EqJoin,
            is ParserItem.EqOp,
            -> {
                if (item.startLine != state.lastLine || item.startLine != state.peak()?.startLine) {
                    state.eqIndents++
                }
                formatLiteral(item)
                state.newlineLast = false
            }
            is ParserItem.AutocompleteHint -> {
                // Remove autocomplete text as they are errors
                state.edits.add(
                    TextEditImpl(
                        RangeImpl(
                            item.textRange.start,
                            item.textRange.end
                        ),
                        ""
                    )
                )
                state.editReasons.add(EditReason.DANGLING_AUTO_COMPLETE)
                state.newlineLast = false
            }
            else -> {
                formatLiteral(item)
                state.newlineLast = false
            }

        }
    }


    /**
     * Push indent tokens into waiting such as enum's next or doif's endi
     */
    internal fun pushWaiting(token: Int, startIndex: Int) {
        if (token in blockStarts) {
            state.waiting.add(0, blockCommands[token]!!)
        }
        if (token in scriptStarts && startIndex in state.scriptStarts) {
            state.waiting.add(0, ENDM_ARRAY)
        }
    }

    /**
     * Remove any waiting indent tokens such as enum's next or DOIF's endi
     */
    internal fun popWaiting(token: Int) {
        if (token == ENDM) {
            state.waiting.clear()
            return
        }
        if (state.waiting.firstOrNull()?.contains(token) == true) {
            state.waiting.removeAt(0)
        }
    }


    companion object {

        internal const val TAG = "Formatter"

        /**
         * Contains block end commands, indexed by their block start command
         */
        internal val blockCommands = mapOf(
            token("doif") to listOf(
                token("elif"),
                token("else"),
                token("endi")
            ),
            token("elif") to listOf(
                token("elif"),
                token("else"),
                token("endi")
            ),
            token("else") to listOf(
                token("endi")
            ),
            token("enum") to listOf(
                token("next")
            ),
            token("etch") to listOf(
                token("next")
            ),
            token("esee") to listOf(
                token("next")
            ),
            token("epas") to listOf(
                token("next")
            ),
            token("econ") to listOf(
                token("next")
            ),
            token("escn") to listOf(
                token("nscn")
            ),
            token("reps") to listOf(
                token("repe")
            ),
            token("loop") to listOf(
                token("ever"),
                token("untl")
            ),
            token("subr") to listOf(
                token("retn")
            )
        )

        /**
         * Convenience object for block starts,
         * Used to determine if a given command starts a block
         */
        internal val blockStarts = blockCommands.keys

        internal val scriptStarts by lazy {
            listOf(
                "scrp",
                "iscr",
                "rscr"
            ).map { token(it.lowercase()) }
        }

//private val blockEnds = listOf(
//    "endi",
//    "next",
//    "nscn",
//    "untl",
//    "ever",
//    "repe"
//).map { token(it) }

        internal val ENDM = token("endm")
        internal val ENDM_ARRAY = listOf(ENDM)

        /**
         * Formats a CAOS document using variant and options
         */
        fun format(variant: String, text: String, options: CaosFormatterOptions? = null): FormatResult {
            val formatter = Formatter(variant, options)
            return formatter.format(text)
        }
    }
}


class FormatException(message: String, throwable: Throwable? = null) : CaosException(message, throwable)

class FormatExceptionWithCaosErrors(message: String, val errors: Array<ParserItem.ErrorVal>, throwable: Throwable? = null) : CaosException(message, throwable)