//private const val TAG = "SymbolCollector"

private val SUBR = token("subr")

private const val MAX_TAIL_TEXT_SIZE = 25

private val baseControlStatements = listOfTokens(
    "subr",
    "scrp",
    "iscr",
    "rscr"
)

private val eatNone = listOfTokens(
    "loop",
    "iscr",
    "rscr",
    // Showing actual conditions would be noisy and not add too much value
    "doif",
    "elif"
)

private val eat1 = listOfTokens(
    "econ",
    "reps",
    "subr"
)

private val eat3 = listOfTokens(
    "enum",
    "etch",
    "esee",
    "epas",
    "escn"
)

private val eat4 = listOfTokens(
    "scrp",
)

private val skipEats = listOfTokens(
    "doif",
    "elif",
    "enum",
    "etch",
    "esee",
    "escn",
    "epas",
    "econ",
    "reps",
    "loop",
)

private val controlStatements = listOfTokens(
    "doif",
    "elif",
    "enum",
    "econ",
    "epas",
    "etch",
    "esee",
    "reps",
    "loop",
    "escn"
)

private val function = listOfTokens(
    "iscr",
    "rscr",
    "subr"
)

private val method = listOfTokens(
    "scrp"
)


@Suppress("NON_EXPORTABLE_TYPE")
@JsExport
@JsName("getDocumentSymbolsFromText")
fun getDocumentSymbols(
    variant: GameVariant,
    text: String,
    addDoifLikeStatements: Boolean = false,
): Array<DocumentSymbol> {
    val parseResult = parseCaos(variant, text)
    return getDocumentSymbols(parseResult, addDoifLikeStatements)
}

@Suppress("NON_EXPORTABLE_TYPE")
@JsExport
fun getDocumentSymbols(
    parserResult: ParseResult,
    addDoifLikeStatements: Boolean = false,
): Array<DocumentSymbol> {
    val scripts = getScriptsFromParseResult(parserResult).toList()
    val items = parserResult.items
        .sortedBy { it.parserIndex }
    val offsets = scopeOffsets(parserResult.originalText)
    return scripts.mapNotNull { script ->
        getDocumentSymbol(
            items,
            offsets.filter { script.textRange.contains(it) },
            script.blockRange,
            script.commandString?.trim() ?: "@macro",
            addDoifLikeStatements
        )
    }.toTypedArray()
}


/**
 * Formats a block range into a document symbol
 */
private fun getDocumentSymbol(
    items: List<ParserItem<*>>,
    offsets: List<com.bedalton.creatures.caos.collectors.BlockRange>,
    range: com.bedalton.creatures.caos.collectors.BlockRange,
    name: String?,
    addDoifLikeStatements: Boolean,
): DocumentSymbol? {
    if (name == null) {
        return null
    }
    val children = offsets.filter { range.startIndex != it.startIndex && range.contains(it) }
        .mapNotNull {
            getDocumentSymbol(items, offsets, it, it.startToken, addDoifLikeStatements)
        }
    return getDocumentSymbol(
        items,
        range,
        name,
        children,
        addDoifLikeStatements
    )
}

/**
 * Gets formatted document symbol given its children
 */
private fun getDocumentSymbol(
    items: List<ParserItem<*>>,
    range: com.bedalton.creatures.caos.collectors.BlockRange,
    name: String?,
    children: List<DocumentSymbol>,
    addDoifLikeStatements: Boolean,
): DocumentSymbol? {
    if (name == null) {
        return null
    }
    if (!addDoifLikeStatements && range.startTok != null && range.startTok !in baseControlStatements) {
        return null
    }

    // Get parameters for command in Symbol definition
    // This is the class in enum statements or the subroutine name in SUBR statements
    var tailItems = getTailItems(items, range)

    // Clear tail items if not expected type
    if (range.startTok == SUBR && tailItems.any { it !is ParserItem.TokenVal && it !is ParserItem.CommandToken}) {
        tailItems = emptyList()
    } else if (range.startTok != SUBR && tailItems.any { it !is ParserItem.IntVal }) {
        tailItems = emptyList()
    }

    // Combine tail items into a string, replacing newlines and multiple whitespace into a single spaced list
    var tailText =  stitch(*tailItems.toTypedArray())
        .replace("\\s+".toRegex(), " ")
        .trim()

    // Trim tail text to max size if needed
    if (tailText.length > MAX_TAIL_TEXT_SIZE) {
        tailText = tailText.substring(0, MAX_TAIL_TEXT_SIZE)
    }

    if (tailText.isNotNullOrBlank()) {
        tailText = " $tailText"
    }

    val kind = getKind(range.startTok)
        ?: return null
    return DocumentSymbolImpl(
        name = name + tailText,
        children = children.toTypedArray(),
        range = range.toRange(),
        selectionRange = RangeImpl(
            range.start,
            end = tailItems.lastOrNull()?.end ?: range.end
        ),
        kind = kind
    )
}

private fun getTailItems(items: List<ParserItem<*>>, range: com.bedalton.creatures.caos.collectors.BlockRange): List<ParserItem<*>> {
    return when (range.startTok) {
        in skipEats -> emptyList()
        in eatNone -> emptyList()
        in eat1 -> getNextTokens(items, range, 1) ?: emptyList()
        in eat3 -> getNextTokens(items, range, 3) ?: emptyList()
        in eat4 -> getNextTokens(items, range, 4) ?: emptyList()
        else -> emptyList()
    }
}


private fun getKind(token: Int?): Int? {
    return when(token) {
        in controlStatements -> {
            SymbolKind.Operator
        }
        in function -> {
            SymbolKind.Function
        }
        in method -> {
            SymbolKind.Method
        }
        else -> {
            null
        }
    }
}

private fun getNextTokens(items: List<ParserItem<*>>, blockRange: RangeWithIndex, count: Int): List<ParserItem<*>>? {
    if (count == 0) {
        return null
    }
    val itemsCount = items.size
    if (itemsCount == 0) {
        return null
    }
    val startIndex = items
        .indexOfFirst index@{
            val parserIndex = blockRange.parserIndex
                    ?: return@index false
            it.parserIndexStart in parserIndex..parserIndex + 1
        }
    if (startIndex < 0) {
        return null
    }
    val out = mutableListOf<ParserItem<*>>()
    var index = startIndex + 1

    while (index < itemsCount && out.size < count) {
        val item = items[index++]
        if (item.isWhitespaceOrComment()) {
            continue
        }
        out.add(item)
    }
    return if (out.size < count) {
        null
    } else {
        out
    }
}