/**
 * Gets all stops based on command words not found in an R/L value context
 */
@JsExport
@JsName("getStops")
fun getStops(variant: String, text: String): IntArray {
    val charStream = CharStreams.fromString(text)
    val lexer = CaosUniversalLexer(charStream)
    return StopsWalker(StopCommands[variant] ?: intArrayOf(), lexer).stops
}

/**
 * Gets the script offsets within a CAOS file
 */
@JsExport
@JsName("scriptOffsets")
fun scriptOffsets(text: String): Array<BlockRange> {
    val charStream = CharStreams.fromString(text)
    val lexer = CaosUniversalLexer(charStream)
    val tokenStream = CommonTokenStream(lexer)
    val parser = CaosUniversalParser(tokenStream)
    val scriptOffsetListener = ScriptOffsetsWalker()
    ParseTreeWalker.DEFAULT.walk(scriptOffsetListener, parser.file())
    return scriptOffsetListener.scriptOffsets
}

@JsExport
fun getCaos2PrayComments(text: String): Array<ParserItem.Caos2Comment> {
    val charStream = CharStreams.fromString(text)
    val lexer = Caos2PrayLexer(charStream)
    val tokenStream = CommonTokenStream(lexer)
    val parser = Caos2PrayParser(tokenStream)
    val walker = Caos2PrayWalker()
    ParseTreeWalker.DEFAULT.walk(walker, parser.file())
    return walker.caos2Comments.toTypedArray()
}
@JsExport
fun getScriptsFromParseResult(parseResult: ParseResult): Array<Script> {
    if (parseResult.scripts.isNotEmpty()) {
        return parseResult.scripts
    }
    val scriptOffsets = scriptOffsets(parseResult.originalText)
        .nullIfEmpty()
        ?: return emptyArray()
    return scriptOffsetsToScriptsArray(scriptOffsets, parseResult.items)
}

@JsExport
fun getWhitespace(text: String): Array<ParserItem<*>> {
    val charStream = CharStreams.fromString(text)
    val lexer = CaosWhitespaceLexer(charStream)
    val tokenStream = CommonTokenStream(lexer)
    val parser = CaosWhitespaceParser(tokenStream)
    val walker = WhitespaceCollector()
    ParseTreeWalker.DEFAULT.walk(walker, parser.file())
    return walker.whitespace.toTypedArray()

}

/**
 * Gets all enclosing control statement ranges.
 * This includes `DOIF`, `REPS`, `ENUM` as well as `SUBR` and `SCRP`, etc.
 */
@JsExport
@JsName("scopeOffsets")
fun scopeOffsets(text: String): Array<BlockRange> {
    val charStream = CharStreams.fromString(text)
    val lexer = CaosUniversalLexer(charStream)
    val tokenStream = CommonTokenStream(lexer)
    val parser = CaosOffsetsParser(tokenStream)
    val scriptOffsetListener = CaosOffsetsWalker()
    ParseTreeWalker.DEFAULT.walk(scriptOffsetListener, parser.file())
    return scriptOffsetListener.offsets
}


/**
 * Create a parserResult from parser items
 * Can be used to parse scripts from parser result using only its enclosed items
 */
@JsExport
@JsName("parseTokens")
fun parseTokens(
    variant: GameVariant,
    text: String,
    items: Array<ParserItem<*>>,
    scriptOffsets: Array<BlockRange> = emptyArray(),
    checkErrors: Boolean? = null,
    checkDelay: Int? = null,
    keepGoing: (() -> Boolean)? = null,
): ParseResult {

    // Ensure variant string is valid
    assertValidVariant(variant)

    // Get CAOS lib for variant
    val lib = CaosLibs[variant.uppercase()]

    // Create a callback that will throw an exception if KeepGoing returns false
    // This is used to abort processing if signaled to stop
    val checkCancelled = createCheckCancelled(checkDelay, keepGoing)

    val nonWhitespaceItems = items.filter { it !is WhitespaceItem }.toTypedArray()

    // Create walker for CAOS file
    val caosWalker = CaosWalker(variant, lib, text, items, checkCancelled)

    // Check for incomplete control statements
    val controlStatementErrors = if (checkErrors != false) {
        val controlStatementWalker = ControlStatementOffsetsTokenWalker(variant, nonWhitespaceItems)
        getControlStatementErrors(controlStatementWalker.statementOffsets, nonWhitespaceItems)
    } else {
        emptyList()
    }

    // Return the processed result
    return ParseResult(
        variant = variant,
        text,
        items = nonWhitespaceItems,
        errors = caosWalker.errors + controlStatementErrors,
        scriptOffsets = scriptOffsets,
        equalityStatements = caosWalker.equalityStatements,
        equalityStatementRanges = caosWalker.equalityStatementRanges,
        commandCalls = caosWalker.commandCalls,
        comments = caosWalker.comments.toTypedArray(),
        caos2Comments = (caosWalker.caos2Comments.nullIfEmpty() ?: items.filter { it.typeToken == TypeTokens.CAOS2_COMMENT }.map { it as ParserItem.Caos2Comment }) .toTypedArray(),
        looseTokens = caosWalker.looseTokens
    )
}

/**
 * Parses the smallest range possible based on enclosing scopes
 */
@JsExport
@JsName("parseCaosNear")
fun parseCaosNear(
    variant: String,
    text: String,
    line: Int,
    character: Int,
    checkErrors: Boolean? = null,
    checkDelay: Int? = null,
    keepGoing: (() -> Boolean)? = null,
): ParseResult {
    // Ensure variant string is valid
    assertValidVariant(variant)

    // Get all containing scopes to try and narrow down the closest one to line/character
    val containingScopes = scopeOffsets(text)
        .filter {
            inRange(
                it,
                line,
                character,
                ignoreColumn = true,
                soft = false
            ) && (it.end.line - it.start.line) > 1
        }
        .sortedByDescending { it.start.line shl 16 + it.start.character }
    // Wait
    var knock = 1
    for (scope in containingScopes) {
        // Get a slice of the script
        var scriptSlice = text.substring(scope.startIndex, scope.endIndex)
        if (scriptSlice.lowercase().endsWith("untl")) {
            scriptSlice += " 1 eq 1"
        }

        // Parse this subsection of script
        val result = parseCaos(
            variant = variant, text = scriptSlice,
            offsetIndex = scope.startIndex,
            offsetLine = scope.start.line,
            offsetColumn = scope.start.character,
            checkErrors = checkErrors,
            checkDelay = checkDelay,
            keepGoing = keepGoing
        )

        // Break out of the first block with control errors, keeping the next
        val controlErrors = result.errors.any {
            it.type == UNTERMINATED_CONTROL_STATEMENT || it.type == UNEXPECTED_CONTROL_TERMINATOR
        }
        if (controlErrors && knock-- > 0) {
            continue
        }
        return result
    }
    return parseCaos(
        variant = variant,
        text = text,
        offsetIndex = 0,
        offsetLine = 0,
        offsetColumn = 0,
        checkErrors = checkErrors,
        checkDelay = checkDelay,
        keepGoing = keepGoing
    )
}


/**
 * Parses CAOS within a given range.
 * Range is expanded to contain a complete control statement
 */
@JsExport
@JsName("parseCaosWithin")
fun parseCaosWithin(
    variant: String,
    text: String,
    startLine: Int,
    startCharacter: Int,
    endLine: Int,
    endCharacter: Int,
    checkErrors: Boolean? = null,
    checkDelay: Int? = null,
    keepGoing: (() -> Boolean)? = null,
): ParseResult {

    // Ensure variant string is valid
    assertValidVariant(variant)

    val containingScopes = scopeOffsets(text)
        .filter {
            (it.end.line - it.start.line) > 1 &&
                    inRange(it, startLine, startCharacter, ignoreColumn = true, soft = true) &&
                    inRange(it, endLine, endCharacter, ignoreColumn = true, soft = true)

        }
        .sortedByDescending { it.start.line shl 16 + it.start.character }
    // Wait
    var knock = 1
    for (scope in containingScopes) {
        val scriptSlice = text.substring(scope.startIndex, scope.endIndex)
        val result = parseCaos(
            variant = variant,
            text = scriptSlice,
            offsetIndex = scope.startIndex,
            offsetLine = scope.start.line,
            offsetColumn = scope.start.character,
            checkErrors = checkErrors,
            checkDelay = checkDelay,
            keepGoing = keepGoing
        )
        val controlErrors = result.errors.any {
            it.type == UNTERMINATED_CONTROL_STATEMENT || it.type == UNEXPECTED_CONTROL_TERMINATOR
        }

        // Break out of the first block with control errors, keeping the next
        if (controlErrors && knock-- > 0) {
            continue
        }
        return result
    }
    return parseCaos(
        variant,
        text,
        offsetIndex = 0,
        offsetLine = 0,
        offsetColumn = 0,
        checkErrors = checkErrors,
        keepGoing = keepGoing
    )
}

/**
 * Parses a CAOS file in its entirety
 */
@JsExport
@JsName("parseCaos")
fun parseCaos(
    variant: String,
    text: String,
    keepGoing: (() -> Boolean)? = null,
): ParseResult {
    return parseCaos(
        variant = variant,
        text = text,
        offsetIndex = 0,
        offsetLine = 0,
        offsetColumn = 0,
        keepGoing = keepGoing
    )
}

/**
 * Parses CAOS using sub-ranges and offsets
 */
internal fun parseCaos(
    variant: String,
    text: String,
    offsetIndex: Int,
    offsetLine: Int,
    offsetColumn: Int,
    checkErrors: Boolean? = null,
    checkDelay: Int? = null,
    keepGoing: (() -> Boolean)? = null,
): ParseResult {
    if (text.isBlank()) {
        return ParseResult(
            variant,
            text,
            emptyArray(),
            emptyArray(),
            emptyArray<Script>(),
            emptyArray(),
            emptyArray(),
            emptyArray(),
            emptyArray(),
            emptyArray(),
            emptyArray()
        )
    }

    // Create lexer
    val charStream = CharStreams.fromString(text)
    val lexer = CaosUniversalLexer(charStream)
    val tokenStream = CommonTokenStream(lexer.apply { reset() })
    val parser = CaosUniversalParser(tokenStream)

    // Create a check cancelled callback if needed
    // Check cancelled will throw an exception processing should stop as defined by keepGoing returning false
    val checkCancelled = createCheckCancelled(checkDelay, keepGoing)

    // Create tokenizer
    val collector = RawTokenizer(
        offsetIndex = offsetIndex,
        offsetLine = offsetLine,
        offsetColumn = offsetColumn,
        checkCancelled = checkCancelled
    )
    lexer.addErrorListener(collector)
    parser.addErrorListener(collector)

    // Try and parse the file
    try {
        val file = parser.file()
        ParseTreeWalker.DEFAULT.walk(collector, file)
    } catch (_: ParseCancelledException) {
        // Processing was terminated by keepGoing returning false
    }
    if (collector.items.isEmpty()) {
        Log.warn("parseCaos()", "No tokens parsed")
    }

    val whitespace: List<WhitespaceItem> = tokenStream.getTokens(0, tokenStream.size() - 1)?.let { tokens ->
        if (variant.uppercase() == "C1" || variant.uppercase() == "C2") {
                tokens.filter { it.channel == CaosUniversalLexer.Channels.WHITESPACE_CHANNEL.id || it.channel == CaosUniversalLexer.Channels.COMMAS_CHANNEL.id }
            } else {
                tokens.filter { it.channel == CaosUniversalLexer.Channels.COMMAS_CHANNEL.id }
            }.flatMap(::whitespaceToTokens)
        } ?: emptyList()

    return parseTokens(
        variant = variant,
        text = text,
        items = (collector.items + whitespace).sortedBy { it.startIndex }.toTypedArray(),
        scriptOffsets = collector.scriptRanges,
        checkErrors = checkErrors,
        checkDelay = checkDelay,
        keepGoing = keepGoing
    )
}


private fun whitespaceToTokens(it: Token): List<WhitespaceItem> {

    val newlineRegex = "\r?\n".toRegex()
    val whitespaces = it.text
        ?: return emptyList()
    val normalizedWhitespace = whitespaces.replace(newlineRegex, "\n")
    if (normalizedWhitespace.none { it == '\n' }) {
        val range = RangeWithIndexImpl(
            it,
            it,
            parserIndex = null
        )
        return ParserItem.Spaces(
            range,
            whitespaces
        ).toListOf()
    }
    if (normalizedWhitespace.all { it == '\n' }) {
        val range = RangeWithIndexImpl(
            it,
            it,
            parserIndex = null
        )
        return ParserItem.NewLine(
            range,
            whitespaces
        ).toListOf()
    }
    var start = it.startIndex
    var newline: Boolean? = null
    var startLine = it.line
    val string = StringBuilder()
    val out = mutableListOf<WhitespaceItem>()
    var startPositionInLine = it.charPositionInLine
    var endPositionInLine = startPositionInLine
    val lastIndex = whitespaces.lastIndex
    for (i in whitespaces.indices) {
        val char = whitespaces[i]
        val charIsNewline = char == '\r' || char == '\n'
        if (newline == null) {
            newline = charIsNewline
        }
        if (charIsNewline != newline || i == lastIndex) {
            val whitespace = string.toString()
            val lines = whitespaces.replace("\r?\n".toRegex(), "\n").count()
            val range = RangeWithIndexImpl(
                start = PositionImpl(
                    startLine,
                    startPositionInLine
                ),
                end = PositionImpl(
                    startLine + lines,
                    endPositionInLine
                ),
                startIndex = start,
                endIndex = start + i,
            )
            startLine += lines
            val item = if (newline) {
                ParserItem.NewLine(
                    textRange = range,
                    value = whitespace
                )
            } else {
                ParserItem.Spaces(
                    textRange = range,
                    value = whitespace
                )
            }
            out.add(item)
            start = it.startIndex + i
            startPositionInLine = endPositionInLine
            string.clear()
        }
        string.append(char)
        if (char == '\n') {
            endPositionInLine = 0
        }
    }
    return out
}

@JsExport
@JsName("collectErrors")
fun collectErrors(
    variant: String,
    text: String,
): Array<ErrorVal> {
    return parseCaos(variant, text).errors
}

private fun getTerminator(start: String): String {
    return when (start.lowercase()) {
        "doif" -> "ENDI"
        "loop" -> "EVER|UNTL"
        "reps" -> "REPE"
        "enum", "esee", "etch", "epas", "econ" -> "NEXT"
        "escn" -> "NSCN"
        "subr" -> "RETN"
        else -> throw Exception("Unexpected start token '$start' for getTerminator()")
    }
}

private fun getControlStatementErrors(statements: List<BlockRange>, items: Array<ParserItem<*>>): List<ErrorVal> {
    return statements.mapNotNull { statement ->
        if (statement.endToken == null && statement.startToken != null) {
            ErrorVal(
                textRange = RangeWithIndexImpl(
                    startIndex = statement.endIndex - 1,
                    endIndex = statement.endIndex,
                    start = PositionImpl(
                        line = statement.end.line,
                        character = maxOf(0, statement.end.character - 1)
                    ),
                    end = PositionImpl(
                        line = statement.end.line,
                        character = statement.end.character
                    )
                ),
                message = "Missing terminating ${getTerminator(statement.startToken)}",
                type = UNTERMINATED_CONTROL_STATEMENT,
                text = stitch(*items.filter { statement.contains(it.textRange) }.toTypedArray())
            )
        } else if (statement.startToken == null) {
            ErrorVal(
                textRange = RangeWithIndexImpl(
                    startIndex = statement.startIndex,
                    endIndex = statement.endIndex,
                    start = PositionImpl(
                        line = statement.start.line,
                        character = statement.end.character
                    ),
                    end = PositionImpl(
                        line = statement.end.line,
                        character = statement.start.character
                    )
                ),
                message = "Unexpected '${statement.endToken!!.uppercase()}'",
                type = UNEXPECTED_CONTROL_TERMINATOR,
                text = stitch(*items.filter { statement.contains(it.textRange) }.toTypedArray())
            )
        } else {
            null
        }
    }
}


/**
 * Creates a callback for stopping parsing if keepGoing() returns false
 * This is used to abort parsing if the caller no longer needs the result
 */
private fun createCheckCancelled(
    checkDelay: Int? = null,
    keepGoing: (() -> Boolean)? = null,
): () -> Unit {
    if (keepGoing == null) {
        return { }
    }
    var cancelled = false
    var exception: Exception? = null
    var checkKicks = 0
    val checkDelayActual = checkDelay ?: 5
    return check@{
        if (checkKicks++ < checkDelayActual) {
            return@check
        }
        checkKicks = 0
        cancelled = cancelled || !keepGoing()
        if (cancelled) {
            throw (exception ?: ParseCancelledException().apply {
                exception = this
            })
        }
    }
}

private fun assertValidVariant(variant: String) {
    if (variant.uppercase() !in setOf("C1", "C2", "CV", "C3", "DS", "SM")) {
        throw Exception("Invalid CAOS variant <$variant>; Expected [C1,C2,CV,C3,DS]")
    }
}