package com.bedalton.common.structs

import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import kotlin.js.JsExport

/**
 * Class to hold a value that should be fetched exactly once
 */
/**
 * Class to hold a value that should be fetched exactly once
 */
class DataCache<T>(get: suspend () -> T?) {

    private var canDispose = true
    private val lock = Mutex(false)
    private var mGet: (suspend () -> T?)? = get

    private var gotten: Boolean = false
    private var cached: T? = null
    private var disposed: Boolean = false

    /**
     * Clear data if it is no longer needed
     */
    fun dispose() {
        if (!canDispose) {
            throw IllegalStateException("Cannot dispose of NeverDispose data cache")
        }
        disposed = true
        mGet = null
        cached = null
    }

    /**
     * Return the cached data if it exists, or fetch it through the get function
     * The get function is cleared after fetch, so it cannot be fetched again
     * if the cached value is cleared
     */
    suspend fun getData(): T? = lock.withLock {
        if (disposed) {
            throw AlreadyDisposedDataCacheException()
        }
        cached?.let {
            return it
        }
        if (gotten) {
            return cached
        }

        val getIt = mGet
            ?: throw AlreadyDisposedDataCacheException()


        val data = try {
            getIt()
        } catch (e: Exception) {
            null
        }
        cached = data
        gotten = true
        this.mGet = null
        data
    }

    fun allowDispose() {
        canDispose = true
    }

    fun neverDispose() {
        canDispose = false
        if (disposed) {
            throw AlreadyDisposedDataCacheException("Cannot set neverDispose as data cache has already been disposed")
        }
    }
}

/**
 * Class to hold a value that should be fetched exactly once
 */
typealias UnsafeDataCache<T> = DataCache<T>


@JsExport
class AlreadyDisposedDataCacheException(
    message: String = "Cache already disposed"
): Exception(message)