object PathUtil {
    fun combine(vararg components: String): String = combine(false, *components)
    fun combine(subFoldersOnly: Boolean, vararg components: String): String {
        if (subFoldersOnly && components.any { it.startsWith("..") }) {
            throw Exception("Cannot build path with parent '..$pathSeparator' components")
        }
        val pathSeparatorChar = if (components.any { it.contains('\\') }) {
            '\\'
        } else {
            pathSeparatorChar
        }
        val componentsExpanded = if (components.firstOrNull() == "~") {
            val expandedComponents = expandTilde("~/")
                .split(pathSeparatorChar)
                .toTypedArray()
            val tail: Array<String> = if (components.size == 1) {
                arrayOf()
            } else {
                components.drop(1).toTypedArray()
            }
            arrayOf(*expandedComponents, *tail)
        } else {
            components
        }
        val out = when (componentsExpanded.size) {
            0 -> ""
            1 -> components[0].normalizeSlashes()
            else -> {
                val out = StringBuilder(
                    // Add initial component
                    components[0].let { first ->
                        if (first.endsWith(pathSeparatorChar)) {
                            first.substring(0, first.lastIndex)
                        } else {
                            first
                        }
                    }
                )

                for (component in components.drop(1)) {
                    if (!component.startsWith(pathSeparator)) {
                        out.append(pathSeparator)
                    }
                    if (component.endsWith(pathSeparator)) {
                        out.append(component.substring(0, component.lastIndex))
                    } else {
                        out.append(component)
                    }
                }
                if (components.last().endsWith(pathSeparator)) {
                    out.append(pathSeparator)
                }
                return removeNesting(out.toString()).normalizeSlashes()
            }
        }
        return out
    }

    /**
     * Normalizes path, dividing along perceived accidentally concatenated paths
     * @return normalized path or null if path seems concatenated and divide is false
     */
    fun normalizePath(pathIn: String, divide: Boolean = false): String? {
        val path = if (isWindows(pathIn)) {
            pathIn.replace('/', '\\')
        } else {
            superUnescape(pathIn)
        }
        if (path.isBlank()) {
            return ""
        }
        val quoteEscape = getEscape(path, "quote")
        var out = try {
            path.replace("([\\^`\\\\])\"".toRegex(), "\$1$quoteEscape")
        } catch (e: Exception) {
            Log.eIf(LOG_DEBUG) { "Failed to escape escaped quote" }
            path
        }

        // Split on internal quote as it should be delimiting paths
        if (out.startsWith("\"") && out.endsWith('"') && out.contains('"')) {
            if (!divide) {
                return null
            }
            val temp = out
                .substring(1)
                .split('"')
                .firstOrNull {
                    it.isNotBlank()
                }
            if (temp != null) {
                out = "\"$temp\""
            }
        }

        // Remove surrounding quotes if any
        val temp = out.stripSurroundingQuotes(2, false)

        // If quoted, allow internal spaces
        val canHaveSpaces = temp != out

        // Use unquoted as output
        out = temp

        // Escape spaces
        out = out.superUnescape(' ')

        // If path could not have spaces, split on a space
        if (!canHaveSpaces) {
            out = out.split(' ')
                .firstOrNull {
                    it.isNotBlank()
                }
                ?.apply {
                    // Path seems to contain another path, but path is not to be divided
                    // so return null
                    if (!divide && out != this) {
                        return null
                    }
                }
                ?: out
        }
        // Remove internally quoted strings
        out = out.replace("\"", "")
        return out
            .replace(quoteEscape, "\"")
            .let {
                combine(out)
            }
    }


    /**
     * Find the relative path between a file and another directory
     * Returns null if the two paths are assumed not to share a common root
     */
    fun relativePath(sourcePath: String, targetPath: String, separatorChar: Char? = null): String? {

        val slashChar = '/'
        val slash = "" + slashChar

        // Get original path separator chars
        val targetPathSeparatorChar = getPathSeparatorChar(targetPath)
        val sourcePathSeparatorChar = getPathSeparatorChar(sourcePath)

        // Get the requested char to use as output
        val outputPathSeparator =
            separatorChar ?: if (targetPathSeparatorChar != sourcePathSeparatorChar) '/' else targetPathSeparatorChar

        // Prepare to replace the possibly different file system separators with the same separator
        val pathSeparatorRegex = "[/\\\\]+".toRegex()

        // Split source path
        var sourcePathComponents = sourcePath.replace(pathSeparatorRegex, slash).split(slashChar)

        // Format and split target path
        val targetPathNormalized = targetPath.replace(pathSeparatorRegex, slash)
        var targetPathComponents = targetPathNormalized.split(slashChar)

        // Pop filename from target array
        val fileName = targetPathComponents.last()
        targetPathComponents = if (targetPathComponents.size > 1) targetPathComponents.dropLast(1) else emptyList()


        // Paths can never equal as they share no common start
        if (targetPathComponents[0] != sourcePathComponents[0] && targetPath[0] != '/' && sourcePath[0] != '/') {
            return null
        }

        // Out variables
        var relativePath = ""

        // Pop source components off until it matches the target path
        while (
            sourcePathComponents.isNotEmpty() &&
            targetPathNormalized.indexOf(sourcePathComponents.joinToString(slash)) != 0
        ) {
            sourcePathComponents = sourcePathComponents.dropLast(1)
            relativePath += "..$outputPathSeparator"
        }

        // Find all path components after the shared root
        val relativePathComponents =
            targetPathComponents.slice(sourcePathComponents.size until targetPathComponents.size)

        // Joint the relative path together if needed
        if (relativePathComponents.isNotEmpty()) {
            relativePath += relativePathComponents.joinToString("" + outputPathSeparator) + outputPathSeparator
        }

        // Return the relative path with filename
        return relativePath + fileName
    }

    // Get an escape sequence to prevent un-escaping a specific char or string
    private fun getEscape(string: String, escapeBase: String, escapeChar: Char = ';'): String {
        var escape = "" + escapeChar + escapeChar + escapeChar + escapeBase + escapeChar + escapeChar + escapeChar
        while (string.contains(escape)) {
            escape = escapeChar + escapeBase + escapeChar
        }
        return escape
    }

    /**
     * Determine the path separator used in a path string
     */
    private fun getPathSeparatorChar(path: String): Char {
//        if (path.contains(pathSeparatorChar)) {
//            return pathSeparatorChar
//        }
        return if (path.contains('\\')) {
            '\\'
        } else if (path.contains('/')) {
            '/'
        } else {
            pathSeparatorChar
        }
    }


    val WINDOWS_ABSOLUTE_PATH_PREFIX = "^[a-zA-Z]:[\\\\/]{1,2}.*".toRegex()

    fun isAbsolute(path: String): Boolean {
        return path.startsWith('/') || path.startsWith("~/") || WINDOWS_ABSOLUTE_PATH_PREFIX.matches(path)
    }

    fun requiresTildeExpansion(path: String): Boolean {
        return path.startsWith("~/")
    }

    fun ensureAbsolutePath(path: String, newRootPath: String): String? {
        if (requiresTildeExpansion(path)) {
            return expandTilde(path)
        }
        if (isAbsolute(path)) {
            return path
        }
        val newPath = combine(newRootPath, path)
        if (!isAbsolute(newPath)) {
            return null
        }
        return newPath
    }


    fun getFileNameWithoutExtension(fileName: String): String? {
        if (fileName.endsWith('/') || fileName.endsWith('\\')) {
            return null;
        }
        val separator = pathSeparator(fileName)
        var startIndex = fileName.lastIndexOf(separator)
        if (startIndex < 0) {
            startIndex = 0
        } else {
            startIndex += 1
        }

        val lastIndex = fileName.lastIndexOf('.')
        val string: String? = when {
            lastIndex < startIndex -> {
                if (startIndex == 0) {
                    fileName
                } else {
                    fileName.substring(startIndex)
                }
            }

            lastIndex > startIndex -> fileName.substring(startIndex, lastIndex)
            else -> null
        }
        return string?.nullIfEmpty()
    }

    fun getExtension(fileName: String): String? {
        val lastIndex = fileName.lastIndexOf('.')
        val extension = when {
            lastIndex < 0 -> null
            lastIndex < fileName.lastIndex -> fileName.substring(lastIndex + 1).let {
                if (it.contains('/') || it.contains('\\')) {
                    null
                } else {
                    it
                }
            }

            else -> null
        }
        return extension.nullIfEmpty()

    }

    /**
     * Gets the closest directory to this path, returning file as is, if it is determined to be a directory
     * Not the most reliable implementation of such a method
     */
    fun getSelfOrParentDirectory(file: String, appendSeparator: Boolean? = null): String? {

        val separator = pathSeparator(file)

        // Internal function to append path separator if desired and separator is missing
        fun String.close(): String {
            return if (appendSeparator != true || this.endsWith(separator)) {
                this
            } else {
                this.ensureEndsWith(separator)
            }
        }
        // If path ends with slash assume it is a directory
        if (file.endsWith(separator)) {
            return file
        }

        // If path has no slash, assume directory if no extension
        val index = file.lastIndexOf(separator)
        if (index < 0) {
            return if (file.contains('.')) {
                null
            } else {
                file.close()
            }
        }

        // Remove last component if it contains a dot
        return if (file.substring(index).contains('.')) {
            file.substring(0 until index).close()
        } else {
            file.close()
        }
    }


    /**
     * Gets the last path components, which may or may not be a file name
     */
    fun getLastPathComponent(path: String, nullIfBlank: Boolean? = null): String? {
        fun String.close(): String? {
            return if (nullIfBlank == true && this.isBlank()) {
                null
            } else {
                this
            }
        }

        val separator = pathSeparator(path)

        return when {
            path.isBlank() -> null
            path == separator.toString() -> "".close()
            else -> {
                val index = path.lastIndexOf(separator)
                when {
                    index < 0 -> path.close()
                    index == path.lastIndex -> "".close()
                    else -> path.substring(index + 1).close()
                }
            }
        }
    }

    @JvmStatic
    fun getWithoutLastPathComponent(aPath: String): String? {
        var path = aPath
        // Unescape whitespace
        if (path.contains('/') && path.contains('\\')) {
            if (path.contains("\\ ")) {
                path = path.replace("\\ ", " ")
            }
            if (path.contains("\\\t")) {
                path = path.replace("\\\t", "\t")
            }
            // Do not unescape newline, as a path should not have newline in it
        }

        val separator = pathSeparator(path)

        val refined = path.trimEnd(separator)
        if (separator == '\\' && refined.matches("[a-zA-Z][:]".toRegex())) {
            return refined + '\\'
        }
        val lastIndex = refined.lastIndexOf(separator)
        if (lastIndex < 0) {
            return null
        }
        return refined.substring(0, lastIndex + 1)
    }


    @JvmStatic
    fun getPathSeparatingLastPathComponent(aPath: String): Pair<String?, String?>? {
        var path = aPath
        // Unescape whitespace
        if (path.contains('/') && path.contains('\\')) {
            if (path.contains("\\ ")) {
                path = path.replace("\\ ", " ")
            }
            if (path.contains("\\\t")) {
                path = path.replace("\\\t", "\t")
            }
            // Do not unescape newline, as a path should not have newline in it
        }

        val separator = pathSeparator(path)
        val components = path.split(separator)
        if (components.isEmpty())
            return null
        return if (components.size == 1) {
            val component = components.first()
            if (separator == '\\' && component.matches("[a-zA-Z][:]".toRegex())) {
                Pair(component + '\\', null)
            } else {
                Pair(null, components.first())
            }
        } else {
            Pair(components.dropLast(1).joinToString(separator.toString()), components.last())
        }
    }

    private fun pathSeparator(path: String?): Char {
        if (path.isNullOrBlank()) {
            return pathSeparatorChar
        }
        if (isWindows(path)) {
            return '\\'
        }
        if (path.contains('/') && path.contains('\\')) {
            if (path.contains("\\ ") || path.contains("\\(") || path.contains("\\)")) {
                return '/'
            } else {
                return '\\'
            }
        }
        if (path.contains('\\')) {
            if (!path.contains("\\ ") && !path.contains("\\(") && !path.contains("\\)")) {
                return '\\'
            }
        }
        return if (!Platform.isWindows() && !Platform.isJs()) {
            pathSeparatorChar
        } else {
            if (path.contains(pathSeparatorChar)) {
                return pathSeparatorChar
            }
            if (path.contains('\\')) {
                return '\\'
            } else if (path.contains('/')) {
                return '/'
            } else {
                pathSeparatorChar
            }
        }

    }

    fun shortestPaths(paths: Collection<String>): Map<String, String> {
        return mShortestPaths(paths)
    }


    fun shortestPaths(paths: Array<String>): Map<String, String> {
        return mShortestPaths(paths.toList())
    }

    fun sharedPath(paths: Collection<String>): String? {
        return mCommonParent(paths)
    }

    fun sharedPath(paths: Array<String>): String? {
        return mCommonParent(paths.toList())
    }
}

expect val applicationSupportPath: String?

expect fun expandTilde(path: String): String


private fun removeNesting(path: String): String {
    val expandedPath = if (path.startsWith('~'))
        expandTilde(path)
    else
        path
    val components = expandedPath.split(pathSeparator)
    val out = mutableListOf<String>()
    for (component in components.drop(1)) {
        if (component == ".")
            continue
        if (component == "..") {
            if (out.isNotEmpty())
                out.removeLast()
            else
                out.add(component)
        } else
            out.add(component)
    }
    return components[0] + pathSeparator + out.joinToString(pathSeparator)
}


private fun String.normalizeSlashes(): String {
    return if (this.contains('/') && this.contains('\\')) {
        if (isWindows(this) || this.count{ it == '\\'} > 1) {
            return this.replace('/', '\\')
        }
        when (pathSeparatorChar) {
            '/' -> this.replace('\\', '/')
            '\\' -> this.replace('/', '\\')
            else -> this.replace('/', pathSeparatorChar)
                .replace('\\', pathSeparatorChar)
        }
    } else {
        this
    }
}


fun String.normalized() = this.lowercase()
    .let {
        if (isWindows(this)) {
            it.replace('/', '\\')
        } else if (it.contains('/')) {
            it.unescape()
        } else {
            it
        }
    }
    .replace('\\', '/')

private fun mShortestPaths(allPaths: Iterable<String>): Map<String, String> {
    val allPathsComponents = allPaths.map { path ->
        Pair(path, path.replace('\\', '/').split('/').reversed().filterNot { it.isBlank() })
    }.filterNot { it.second.isEmpty() }

    val sharedEnds = allPathsComponents.map { it.second.first().lowercase() }.distinct().map { tail ->
        allPathsComponents.filter { it.second.first().lowercase() == tail }
    }

    val out = mutableMapOf<String, String>()
    for (shared in sharedEnds) {
        for ((original, components) in shared) {
            var matches = shared.filterNot { it.first.lowercase() == original.replace('\\', '/').lowercase() }
            var temp = components[0]
            var hasNext = true
            loop@ for (i in components.indices.drop(1)) {
                if (!hasNext) {
                    continue@loop
                }
                val component = components[i].lowercase()
                if (matches.isEmpty()) {
                    hasNext = false
                    continue@loop
                }
                matches = matches.filter { it.second.size > i && it.second[i].lowercase() == component }
                temp = "${components[i]}/$temp"
            }
            out[original] = if (original.endsWith('/')) {
                temp
            } else {
                temp.trim('/')
            }
        }
    }
    return out
}

private fun mCommonParent(allPaths: Iterable<String>): String? {
    val normalized = allPaths.map { it.replace('\\', '/') }
    val prefix = if (normalized.all { it.firstOrNull() == '/' }) "/" else ""
    val allPathsComponents = normalized.map { path ->
        path.split('/').filter { it.isNotBlank() }
    }.toMutableList().nullIfEmpty()
        ?: return null
    val maxSharedLength = allPathsComponents.minOf { it.size }
    val out = mutableListOf<String>()
    val base = allPathsComponents.removeAt(0)
    for (i in 0 until maxSharedLength) {
        val component = base[i]
        if (!allPathsComponents.all { it[i] == component }) {
            break
        }
        out.add(component)
    }
    if (out.isEmpty()) {
        return null
    }
    return prefix + out.joinToString('/')

}

fun isWindows(path: String): Boolean {
    return path.contains("^.:\\\\".toRegex())
}