@file:Suppress("unused")

package com.bedalton.log

const val LOG_DEBUG = "DEBUG"

const val LOG_VERBOSE = "verbose"

const val LOG_PROGRESS = "progress"

@Suppress("MemberVisibilityCanBePrivate")
object LogModes {
    val DEBUG get() = LOG_DEBUG
    val VERBOSE get() = LOG_VERBOSE
    val PROGRESS get() = LOG_PROGRESS

    fun debug(on: Boolean) {
        Log.setMode(DEBUG, on)
    }

    fun verbose(on: Boolean) {
        Log.setMode(VERBOSE, on)
    }

    fun progress(on: Boolean) {
        Log.setMode(PROGRESS, on)
    }
}

fun logProgress(log: Boolean) {
    Log.setMode(LOG_PROGRESS, log)
}
