package com.bedalton.creatures.caos.hints

import com.bedalton.creatures.caos.collectors.CommandCall
import com.bedalton.creatures.caos.collectors.ConditionCommand
import com.bedalton.creatures.caos.libs.CaosVariant
import com.bedalton.creatures.caos.libs.GameVariant
import com.bedalton.creatures.caos.libs.ICaosParameter
import com.bedalton.creatures.caos.libs.ValueType
import com.bedalton.creatures.caos.server.InlayHint
import com.bedalton.creatures.caos.utils.like
import com.bedalton.creatures.caos.utils.likeAny
import com.bedalton.creatures.caos.utils.notLikeAny
import com.bedalton.creatures.caos.utils.nullIfEmpty

internal val setLike = setOf("SETV", "SETS", "SETA")

internal val SKIP_LAST = setOf("PUHL", "PUPT", "CLS2")

enum class ParameterHintsProvider(
    override val option: String,
    override val description: String,
    override val priority: Int = 0
) : CommandInlayHintsProvider {

    PARAMETER_NAME_HINT("parameterHints.showParameterHints", "Show parameter names before expression") {
        override fun isApplicable(variant: CaosVariant, element: CommandCall): Boolean {
            return !element.inEqualityExpression &&
                    element.type != ValueType.CONDITION.value &&
                    element.command != ConditionCommand &&
                    element.command.command notLikeAny setLike
        }

        override fun provideHints(variant: CaosVariant, element: CommandCall): List<InlayHint> {
            val referencedCommand = element.command
            if (referencedCommand.command in setLike) {
                return EMPTY_INLAY_LIST
            }
            val skipLast = skipLast(element)
            val parameterStructs = referencedCommand.parameters
            val parameters = getParametersAsStrings(parameterStructs, skipLast)
            val arguments = element.arguments
            return arguments.mapIndexedNotNull map@{ i, argument ->
                if (referencedCommand.parameters.getOrNull(i)?.typeId == ValueType.CONDITION.value) {
                    return@map null
                }
                val parameterName = parameters
                    .getOrNull(i)
                    .nullIfEmpty()
                    ?: return@map null
                val position = argument.textRange.start
                InlayHintImpl(position, "$parameterName:", InlayKind.Parameter)
            }.toList()
        }
    },

    SETV_PARAMETER_NAME_HINT("setvParameterHints", "Show parameter names before expression") {
        override fun isApplicable(variant: CaosVariant, element: CommandCall): Boolean {
            return !element.inEqualityExpression &&
                    element.type != ValueType.CONDITION.value &&
                    element.command.command likeAny setLike
        }

        override fun provideHints(variant: GameVariant, element: CommandCall): List<InlayHint> {
            val arguments = element.arguments

            val lvalueElement = arguments.firstOrNull()
                ?: return EMPTY_INLAY_LIST

            val command = (lvalueElement as? CommandCall)?.command
                ?: return EMPTY_INLAY_LIST

            val parameters = command.parameters
            val lastArgument = arguments.lastOrNull()

            // Build list of parameter names, appending lvalueName from command definition as needed
            val parameterNames = if (!skipLast(lvalueElement) && command.lvalueName.nullIfEmpty() != null) {
                parameters.map { it.name.nullIfEmpty() } + command.lvalueName!!
            } else {
                parameters.map { it.name.nullIfEmpty() }
            }
            val out = if (lastArgument != null) {
                lvalueElement.arguments + lastArgument
            } else {
                lvalueElement.arguments
            }
            val hints = out.mapIndexedNotNull map@{ i, argument ->
                val parameter = (argument as? CommandCall)?.command?.lvalueName
                    ?: parameterNames.getOrNull(i)
                    ?: return@map null

                if (parameter like "var") {
                    return@map null
                }
                val position = argument.textRange.start

                InlayHintImpl(position, "$parameter:")
            } + element.command.parameters.map { it.name }.let { parameterStrings ->
                element.arguments.dropLast(1).mapIndexedNotNull map@{ i, argument ->
                    val parameter = parameterStrings.getOrNull(i)
                        ?: return@map null
                    if (parameter like "var") {
                        return@map null
                    }
                    val position = argument.textRange.start
                    InlayHintImpl(position, "$parameter:")
                }
            }
            return hints.distinct()
        }
    }
    ;

    companion object {


        private fun skipLast(element: CommandCall): Boolean {
            return if (element.command.command.uppercase() in setLike) {
                val firstArg = element.arguments.firstOrNull()
                val commandString = (firstArg as? CommandCall)?.command?.command
                return commandString in SKIP_LAST
            } else {
                false
            }
        }

        private fun getParametersAsStrings(parameters: Array<ICaosParameter>, skipLast: Boolean): List<String> {
            return if (skipLast) {
                (0 until parameters.lastIndex).map { i -> parameters[i].name }
            } else {
                parameters.map { it.name }
            }
        }
    }
}