package com.bedalton.common.structs

import kotlinx.serialization.descriptors.SerialDescriptor
import kotlinx.serialization.encoding.CompositeDecoder

fun CompositeDecoder.decodeNullableStringElement(
    descriptor: SerialDescriptor,
    index: Int
): String? = decodeSerializableElement(descriptor, index, nullableStringSerializer)


fun CompositeDecoder.decodeNullableByteElement(
    descriptor: SerialDescriptor,
    index: Int
): Byte? = decodeSerializableElement(descriptor, index, nullableByteSerializer)


fun CompositeDecoder.decodeNullableShortElement(
    descriptor: SerialDescriptor,
    index: Int
): Short? = decodeSerializableElement(descriptor, index, nullableShortSerializer)

fun CompositeDecoder.decodeNullableIntElement(
    descriptor: SerialDescriptor,
    index: Int
): Int? = decodeSerializableElement(descriptor, index, nullableIntSerializer)


fun CompositeDecoder.decodeNullableLongElement(
    descriptor: SerialDescriptor,
    index: Int
): Long? = decodeSerializableElement(descriptor, index, nullableLongSerializer)


fun CompositeDecoder.decodeNullableFloatElement(
    descriptor: SerialDescriptor,
    index: Int
): Float? = decodeSerializableElement(descriptor, index, nullableFloatSerializer)


fun CompositeDecoder.decodeNullableDoubleElement(
    descriptor: SerialDescriptor,
    index: Int
): Double? = decodeSerializableElement(descriptor, index, nullableDoubleSerializer)


fun CompositeDecoder.decodeNullableBooleanElement(
    descriptor: SerialDescriptor,
    index: Int
): Boolean? = decodeSerializableElement(descriptor, index, nullableBooleanSerializer)

fun CompositeDecoder.decodeStringListElement(
    descriptor: SerialDescriptor,
    index: Int
): List<String> = decodeSerializableElement(descriptor, index, stringListSerializer)

fun CompositeDecoder.decodeNullableStringListElement(
    descriptor: SerialDescriptor,
    index: Int
): List<String>? = decodeSerializableElement(descriptor, index, nullableStringListSerializer)

fun CompositeDecoder.decodeStringArrayElement(
    descriptor: SerialDescriptor,
    index: Int
): Array<String> = decodeSerializableElement(descriptor, index, stringArraySerializer)

fun CompositeDecoder.decodeNullableStringArrayElement(
    descriptor: SerialDescriptor,
    index: Int
): Array<String>? = decodeSerializableElement(descriptor, index, nullableStringArraySerializer)
