package com.bedalton.common.util


private var mPathSeparator: Char = getDefaultPathSeparator()

actual val pathSeparatorChar: Char get() = mPathSeparator
actual val pathSeparator: String get() = mPathSeparator.toString()

fun setPathSeparator(separator: Char) {
    mPathSeparator = separator
}

private fun getDefaultPathSeparator(): Char {
    return if (js("require != null") as Boolean) {
        try {
            (nodeRequireSafe("path")?.sep as String?)?.getOrNull(0)
                ?: '/'
        } catch (e: Exception) {
            '/'
        } catch (e: Error) {
            '/'
        }
    } else {
        '/'
    }
}

actual val applicationSupportPath: String? = null

actual fun expandTilde(path: String): String {
    if (js("typeof window !== 'undefined'") as Boolean) {
        throw Exception("Cannot expand tilde in path in browser")
    }
    val process = js("process")
    return PathUtil.combine(process.env.HOME as String, path.substring(1))
}


actual val platform: Platform
    get() = Platform.JS

internal actual fun isJVM(): Boolean = false