package com.bedalton.log.internal

import com.bedalton.log.*
import kotlin.math.min

private var lastLineLength = 0

/**
 * Default JS Logging instance. Uses console logging methods
 */
internal actual object DefaultLoggerObject: ILoggerObject {
    actual override val prependLogType: Boolean = false

    actual override fun log(replace: Boolean, message: String, color: LoggerColor?) {
        val finalMessage = wrap(color, message)
        if (replace) {
            logReplace(finalMessage, console::log)
        } else {
            console.log(finalMessage)
        }
        lastLineLength = finalMessage.length
    }

    actual override fun info(replace: Boolean, message: String, color: LoggerColor?) {
        val finalMessage = wrap(color, message)
        if (replace) {
            logReplace(finalMessage, console::info)
        } else {
            console.info(finalMessage)
        }
        lastLineLength = finalMessage.length
    }

    actual override fun warning(message: String, color: LoggerColor?) {
        val finalMessage = wrap(color, message)
        lastLineLength = finalMessage.length
        console.warn(finalMessage)
    }

    actual override fun logMemory() {
        console.log("Cannot log memory")
        lastLineLength = "Cannot log memory".length
        val process = nodeRequireSafe("process")
        if (process != null && process.hasOwnProperty("memoryUsage") as Boolean) {
            console.log(process.memoryUsage())
        }
    }

    actual override fun error(message: String, color: LoggerColor?) {
        val finalMessage = wrap(color, message)
        lastLineLength = finalMessage.length
        console.error(finalMessage) //console.warn("\\033[33m$message")
    }

    actual override fun getColorPrefix(color: LoggerColor?): String? {
        return getLogColorPrefix(color)
    }

    private fun wrap(color: LoggerColor?, message: String): String {
        val colorPrefix = getColorPrefix(color)
        return if (colorPrefix != null) {
            colorPrefix + message.stripNamespacePrefix()  + ConsoleColors.RESET
        } else {
            message.stripNamespacePrefix()
        }
    }
}


private fun logReplace(message: String, fallback: (message: String) -> Unit) {
    if (js("typeof window !== 'undefined'") as Boolean) {
        fallback(message)
        return
    }
    val stdout = nodeRequireSafe("process", "stdout")?.stdout
    if (stdout == null || stdout.constructor?.name != "WriteStream") {
        fallback(message)
        return
    }

    val readline = nodeRequireSafe("readline", "clearLine", "cursorTo")
    if (readline == null) {
        fallback(message)
        return
    }
    readline.clearLine(stdout)
    readline.cursorTo(stdout, 0)
    val underflow = message.length - lastLineLength
    val tail = if (underflow > 0) {
        " ".repeat(underflow)
    } else {
        ""
    }
    val messagePadded = (message + tail)
    stdout.write(messagePadded.substring(0, min((stdout.columns as Number).toInt(), messagePadded.length)), "utf8")
}