    /**
     * Logs a trace message, possibly replacing last log line
     */
    @Deprecated(
        message = "Trace with \"replace\" parameter is deprecated and may be removed in the future",
        replaceWith = ReplaceWith(
            "t(color, message)",
            imports = ["bedalton.creatures.util.Log"]
        )
    )
    fun t(replace: Boolean, color: LoggerColor?, message: () -> String) {
        contract {
            callsInPlace(message, InvocationKind.AT_MOST_ONCE)
        }
        if (!silent && logLevel.value >= LogLevel.TRACE.value) {
            loggerObject.info(
                replace,
                format(
                    "TRACE",
                    null
                ) { message() + "\n" + shiftLogStackFromCallStack(Exception().stackTraceToString()) },
                color
            )
        }
    }

