    @JvmStatic
    fun e2(className: String, message: String) {
        e2(className, message)
    }

    /**
     * Logs a warning message formatted with a classname
     */
    @JvmStatic
    fun e2(className: String, color: LoggerColor?, message: () -> String) {
        contract {
            callsInPlace(message, InvocationKind.AT_MOST_ONCE)
        }
        if (!silent && logLevel.value >= LogLevel.LOG_2.value) {
            loggerObject.warning(format("WARN", className, message), color)
        }
    }

    /**
     * Logs a warning message formatted with a classname
     */
    @JvmStatic
    fun e2(className: String, color: LoggerColor?, message: String) {
        if (!silent && logLevel.value >= LogLevel.LOG_2.value) {
            loggerObject.warning(format("WARN", className, message), color)
        }
    }

    /**
     * Formats a message with a given kind and classname
     * Kind being along the lines of info, error, warning
     */
    internal inline fun format(kind: String, className: String?, message: () -> String): String {
        contract {
            callsInPlace(message, InvocationKind.AT_MOST_ONCE)
        }
        return format(kind, className, message())
    }

    /**
     * Formats a message with a given kind and classname
     * Kind being along the lines of info, error, warning
     */
    internal fun format(kind: String, className: String?, message: String): String {
        val prependLog = (loggerObject.prependLogType ?: DefaultLoggerObject.prependLogType)
        val prefix = if (prependLog && !hasMode(LOG_NO_PRINT_PREFIX)) {
            "**${kind}** "
        } else {
            ""
        }
        return "$prefix${if (!className.isNullOrBlank()) "$className::" else ""}${message}"
    }

    /**
     * Log memory debug information if available to console
     */
    fun logMemory() {
        loggerObject.logMemory()
    }

    /**
     * Sets if a mode is active
     */
    @JvmStatic
    fun hasMode(mode: String): Boolean {
        return mode in modes
    }

    /**
     * Sets a mode state for this logger
     */
    @JvmStatic
    fun setMode(mode: String, active: Boolean) {
        val hasMode = mode in modes
        if (active == hasMode) {
            return
        }
        if (active) {
            modes.add(mode)
        } else {
            modes.remove(mode)
        }
    }

    /**
     * Set logger to use with the global Log object
     */
    @JvmStatic
    fun setLogger(logger: ILoggerObject) {
        loggerObject = logger
    }

    /**
     * Switch back to using the default logger
     */
    @JvmStatic
    fun useDefaultLogger() {
        loggerObject = DefaultLoggerObject
    }

    fun namespaceLogComponents(statement: String): Pair<String?, String> {
        return namespacePrefixRegex.matchEntire(statement)
            ?.groupValues
            ?.let {
                Pair(it[1], it[2])
            }
            ?: Pair(null, statement)
    }
}


@Suppress("RegExpUnnecessaryNonCapturingGroup")
private val stackTraceRegex =
    "^\\s*java\\.lang\\.Exception(?:(\\s*at com\\.bedalton\\.log\\.Log[.\$][^\\n]*\\n)*)".toRegex(
        setOf(
            RegexOption.IGNORE_CASE,
            RegexOption.MULTILINE
        )
    )

private fun shiftLogStackFromCallStack(stack: String): String {
    return stack.replace(stackTraceRegex, "")
}