package com.bedalton.creatures.caos.collectors

import com.bedalton.creatures.caos.server.PositionImpl
import com.bedalton.creatures.caos.server.RangeWithIndex
import com.bedalton.creatures.caos.utils.insertFront
import com.bedalton.creatures.caos.utils.token

/**
 * Collects all control statement offsets
 * Control statements being ENUM..NEXT, REPS..REPE, etc..
 */
class ControlStatementOffsetsTokenWalker(variant: String, tokens: Array<ParserItem<*>>) {
    private val stack: MutableList<Pair<Int, ParserItem.CommandToken>> = mutableListOf()
    private lateinit var mScriptOffsets: MutableList<BlockRange>
    val statementOffsets: List<BlockRange> by lazy {
        calculateOffsets(tokens)
    }
    private var depth = 0
    private var skipNextNext: Boolean = false
    private val isNewVariant: Boolean = variant.uppercase() !in listOf("C1", "C2")
    private var isDDe: Boolean = false
    private val dde: Int = token("dde:")


    private fun calculateOffsets(tokens: Array<ParserItem<*>>): List<BlockRange> {

        if (this::mScriptOffsets.isInitialized) {
            return mScriptOffsets
        }

        mScriptOffsets = mutableListOf()

        if (tokens.isEmpty()) {
            return emptyList()
        }

        for (token in tokens) {
            if (token is ParserItem.CommandToken) {
                enterWord(token)
            }
        }
        enterEof(tokens.last())
        return mScriptOffsets
    }

    private fun enterWord(ctx: ParserItem.CommandToken) {
        val token = ctx.token
        isDDe = !isNewVariant && token == dde
        when (token) {
            in controlStatementStart -> enterControlStatementStart(token, ctx)
            in controlStatementStop -> exitControlStatementEnd(token, ctx)
            in scriptEnclosures -> closeScript(token, ctx)
        }
        skipNextNext = isNewVariant && token in hasNextNext
    }

    /**
     * Control statement starts are DOIF,ENUM,REPS,LOOP, etc
     */
    private fun enterControlStatementStart(token: Int, ctx: ParserItem.CommandToken) {
        isDDe = false
        stack.insertFront(Pair(token, ctx))
        depth++
    }

    /**
     * Control statement ends are ENDI,NEXT,REPE,UNTL, etc
     */
    private fun exitControlStatementEnd(token: Int, ctx: ParserItem.CommandToken) {
        isDDe = false
        if (skipNextNext) {
            skipNextNext = false
            if (token == NEXT) {
                return
            }
        }
        val start = when (token) {
            ENDI -> DOIF
            EVER, UNTL -> LOOP
            RETN -> if (stack.size <= 1) SUBR else null
            NEXT -> ENUM
            REPE -> REPS
            NSCN -> ESCN
            else -> null
        } ?: return
        popUntil(start, ctx)
    }

    /**
     * Script starts are SCRP,ISCR,RSCR
     */
    private fun closeScript(token: Int, ctx: ParserItem.CommandToken) {
        // Ignore DDE: SCRP
        if (isDDe) {
            isDDe = false
            if (token == SCRP) {
                return
            }
        }
        isDDe = false
        popAll(ctx)
        depth = 0
    }

    private fun enterEof(ctx: ParserItem<*>) {
        popAll(ctx)
    }

    private fun popAll(ctx: ParserItem<*>) {
        depth = 0
        while (true) {
            val item = stack.removeFirstOrNull()
                ?: return
            popMismatch(item.second.value, item.second.textRange, ctx.textRange)
        }
    }

    private fun popUntil(startToken: IntArray, endCtx: ParserItem.CommandToken) {
        var didFindStart = false
        while (true) {
            val item = stack.removeFirstOrNull()
                ?: break
            depth--
            if (depth < 0)
                depth = 0
            if (item.first !in startToken) {
                popMismatch(item.second.value, item.second.textRange, endCtx.textRange)
            } else {
                didFindStart = true
                popMatch(item.second.value, endCtx.value.lowercase(), item.second.textRange, endCtx.textRange)
                break
            }
        }
        if (!didFindStart) {
            val start = endCtx.textRange
            val end = endCtx.textRange
            mScriptOffsets.add(
                BlockRange(
                    startToken = null,
                    endToken = endCtx.value,
                    start = start,
                    end = end,
                    null,
                    depth = depth
                )
            )
        }
    }


    private fun popMatch(startCommand: String, endToken: String, start: RangeWithIndex, end: RangeWithIndex) {
        mScriptOffsets.add(
            BlockRange(
                startToken = startCommand.lowercase(),
                endToken = endToken.lowercase(),
                start = start,
                end = end,
                null,
                depth = depth
            )
        )
    }

    private fun popMismatch(startCommand: String, start: RangeWithIndex, newStart: RangeWithIndex) {
        mScriptOffsets.add(
            BlockRange(
                startToken = startCommand,
                endToken = null,
                startIndex = start.startIndex,
                endIndex = maxOf(start.endIndex, newStart.startIndex),
                start = PositionImpl(
                    line = start.start.line,
                    character = start.start.character
                ),
                end = PositionImpl(
                    line = newStart.start.line,
                    character = maxOf(0, newStart.start.character - 1)
                ),
                null,
                depth = depth
            )
        )
    }

    companion object {
        private val SCRP = token("scrp")
        private val DOIF = intArrayOf(token("doif"))
        private val ESCN = intArrayOf(token("escn"))
        private val ENUM = intArrayOf(
            token("enum"),
            token("epas"),
            token("etch"),
            token("esee"),
            token("econ")
        )
        private val LOOP = intArrayOf(token("loop"))
        private val SUBR = intArrayOf(token("subr"))
        private val REPS = intArrayOf(token("reps"))


        // Endings
        private val ENDI = token("endi")
        private val EVER = token("ever")
        private val NEXT = token("next")
        private val NSCN = token("nscn")
        private val REPE = token("repe")
        private val RETN = token("retn")
        private val UNTL = token("untl")

        private val controlStatementStart: IntArray = DOIF + ESCN + ENUM + LOOP + SUBR + REPS
        private val controlStatementStop: IntArray = intArrayOf(ENDI, NSCN, NEXT, EVER, UNTL, RETN, REPE)

        private val scriptEnclosures: IntArray = intArrayOf(
            SCRP,
            token("iscr"),
            token("rscr"),
            token("endm")
        )

        private val hasNextNext = arrayOf(token("pray"), token("hist"))
    }
}