package com.bedalton.creatures.caos.formatter

import com.bedalton.creatures.caos.collectors.ParserItem
import com.bedalton.creatures.caos.collectors.end
import com.bedalton.creatures.caos.collectors.start
import com.bedalton.creatures.caos.collectors.startIndex
import com.bedalton.creatures.caos.formatter.EditReason.*
import com.bedalton.creatures.caos.server.RangeImpl
import com.bedalton.creatures.caos.server.TextEditImpl
import com.bedalton.creatures.caos.utils.token


internal fun Formatter.formatByteString(item: ParserItem<*>) {
    ensureSpace(item)
    val oldText = item.text
    val spaceBetween = if (state.spaceBetweenByteStingBrackets) " " else ""
    val items = oldText.substring(1, oldText.lastIndex).trim()
        .replace("\\s\\s+".toRegex(), " ")
    val newText = "[$spaceBetween$items$spaceBetween]"
    if (oldText != newText) {
        state.edits.add(
            TextEditImpl(
                RangeImpl(
                    item.textRange.start,
                    item.textRange.end
                ),
                newText
            )
        )
        state.editReasons.add(SPACE_BETWEEN_BRACKETS)
    }
    state.out.append(newText)
}


/**
 * Format a literal value like a number or string
 */
internal fun Formatter.formatLiteral(item: ParserItem<*>) {
    ensureSpace(item)
    val oldText = item.text
    if (!oldText.contains("  ")) {
        state.out.append(oldText)
        return
    }
    val newText = oldText.replace("\\s\\s+".toRegex(), " ")
    if (oldText != newText) {
        state.edits.add(
            TextEditImpl(
                RangeImpl(
                    item.start,
                    item.end
                ),
                newText
            )
        )
        state.editReasons.add(SPACE_TOKEN)
    }
    state.out.append(newText)
}

internal fun Formatter.formatCommandToken(item: ParserItem.CommandToken) {
    popWaiting(item.token)
    ensureSpace(item)
    val oldText = item.text
    val newText = item.text.lowercase()
    if (oldText != newText) {
        state.edits.add(
            TextEditImpl(
                RangeImpl(
                    item.start,
                    item.end
                ),
                newText
            )
        )
        state.editReasons.add(CASE_COMMAND)
    }
    state.out.append(newText)

    pushWaiting(item.token, item.startIndex)
}

internal fun Formatter.formatCommandToken(item: ParserItem.CompoundCommandToken) {
    if (item.tokens.size == 1) {
        popWaiting(item.tokens.first().token)
    }
    ensureSpace(item)
    val oldText = item.text
    val newText = item.tokens.joinToString(" ") { token(it.token) }.trim()
    if (oldText != newText) {
        state.edits.add(
            TextEditImpl(
                RangeImpl(
                    item.textRange.start,
                    item.textRange.end
                ),
                newText
            )
        )
        state.editReasons.add(SPACES_BETWEEN_COMMANDS)
    }
    state.out.append(newText)
    if (item.tokens.size == 1) {
        pushWaiting(item.tokens.first().token, item.tokens.first().startIndex)
    }
}

internal fun Formatter.formatIndexedVariable(item: ParserItem.IndexedVar) {
    ensureSpace(item)
    val oldText = item.text
    val newText = oldText.lowercase()
    if (oldText != newText) {
        state.edits.add(
            TextEditImpl(
                RangeImpl(
                    item.textRange.start,
                    item.textRange.end
                ),
                newText
            )
        )
        state.editReasons.add(CASE_VARIABLE)
    }
    state.out.append(newText)
}