@file:Suppress("unused")

package com.bedalton.creatures.caos.formatter

import com.bedalton.creatures.caos.server.TextEdit
import kotlin.js.JsExport
import kotlin.js.JsName

@Suppress("NON_EXPORTABLE_TYPE")
@JsExport
data class FormatResult(
    @JsName("formattedText")
    val formattedText: String,
    @JsName("oldText")
    val oldText: String,
    @JsName("edits")
    val edits: Array<TextEdit>,
    @JsName("editReasons")
    val editReasons: Array<EditReason>
) {
    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is FormatResult) return false

        if (formattedText != other.formattedText) return false
        if (oldText != other.oldText) return false
        if (!edits.contentEquals(other.edits)) return false

        return true
    }

    override fun hashCode(): Int {
        var result = formattedText.hashCode()
        result = 31 * result + oldText.hashCode()
        result = 31 * result + edits.contentHashCode()
        return result
    }
}


enum class EditReason(val commonName: String) {
    DANGLING_AUTO_COMPLETE("auto-complete.dangling"),
    FORMAT_CAOS2("spacing.caos2pray"),
    COMMENT("comment"),
    SPACE_BETWEEN_BRACKETS("spacing.brackets"),
    SPACES_BETWEEN_COMMANDS("spacing.command"),
    SPACE_NEEDED("spacing.needed"),
    SPACE_TOO_MANY("spacing.remove"),
    NEWLINES_NEEDED("newline.add"),
    NEWLINES_TOO_MANY("newline.remove"),
    SPACE_TOKEN("spacing.tokens"),
    CASE_COMMAND("case.command"),
    CASE_VARIABLE("case.variable"),
    TAB_CHANGE("spacing.tabs")
}