package com.bedalton.creatures.caos.collectors

import com.bedalton.creatures.caos.formatter.Formatter.Companion.ENDM
import com.bedalton.creatures.caos.server.Range
import com.bedalton.creatures.caos.server.RangeWithIndex
import com.bedalton.creatures.caos.server.inRange
import com.bedalton.creatures.caos.utils.nullIfEmpty
import kotlin.js.JsExport
import kotlin.js.JsName


@JsExport
data class Script(
    @JsName("commandString")
    val commandString: String?,
    @JsName("items")
    val items: Array<ParserItem<*>>,
    @Suppress("NON_EXPORTABLE_TYPE")
    @JsName("textRange")
    val textRange: RangeWithIndex,
) {

    val key get() = commandString?.uppercase()

    val blockRange: BlockRange by lazy {
        val last = items.lastOrNull()
        val end = if (last is ParserItem.CommandToken && last.token == ENDM) {
            "endm"
        } else {
            null
        }
        BlockRange(
            key,
            end,
            textRange,
            items.firstOrNull()?.parserIndex,
            0
        )
    }

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is Script) return false

        if (key != other.key) return false
        if (!items.contentEquals(other.items)) return false

        return true
    }

    override fun hashCode(): Int {
        var result = key?.hashCode() ?: 0
        result = 31 * result + items.contentHashCode()
        return result
    }
}

@Suppress("NON_EXPORTABLE_TYPE")
@JsExport
@JsName("ParseResult")
data class ParseResult(
    @JsName("variant")
    val variant: String,
    @JsName("originalText")
    val originalText: String,
    @JsName("items")
    val items: Array<ParserItem<*>>,
    @JsName("errors")
    val errors: Array<ParserItem.ErrorVal>,
    @JsName("scripts")
    val scripts: Array<Script>,
    @JsName("equalityStatements")
    val equalityStatements: Array<EqualityStatement>,
    @JsName("equalityStatementRanges")
    val equalityStatementRanges: Array<RangeWithIndex>,
    @JsName("commandCalls")
    val commandCalls: Array<CommandCall>,
    @JsName("comments")
    val comments: Array<ParserItem.Comment>,
    @JsName("caos2Comments")
    val caos2Comments: Array<ParserItem.Caos2Comment>,
    @JsName("looseTokens")
    val looseTokens: Array<ParserItem<*>>,
) {

    @JsName("withScriptOffsets")
    internal constructor(
        variant: String,
        originalText: String,
        items: Array<ParserItem<*>>,
        errors: Array<ParserItem.ErrorVal>,
        scriptOffsets: Array<BlockRange>,
        equalityStatements: Array<EqualityStatement>,
        equalityStatementRanges: Array<RangeWithIndex>,
        commandCalls: Array<CommandCall>,
        comments: Array<ParserItem.Comment>,
        caos2Comments: Array<ParserItem.Caos2Comment>,
        looseTokens: Array<ParserItem<*>>,
    ) : this(
        variant = variant,
        originalText = originalText,
        items = items,
        errors = errors,
        scripts = scriptOffsetsToScriptsArray(scriptOffsets, items),
        equalityStatements,
        equalityStatementRanges,
        commandCalls,
        comments,
        caos2Comments,
        looseTokens
    )

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is ParseResult) return false

        if (!items.contentEquals(other.items)) return false
        if (!scripts.contentEquals(other.scripts)) return false

        return true
    }

    override fun hashCode(): Int {
        var result = items.contentHashCode()
        result = 31 * result + scripts.contentHashCode()
        return result
    }
}

internal fun scriptOffsetsToScriptsArray(
    scriptOffsets: Array<BlockRange>,
    items: Array<ParserItem<*>>,
): Array<Script> {
    return scriptOffsets.mapNotNull script@{ range ->
        val scriptItems = items.filter { it.textRange inside range }
            .nullIfEmpty()
            ?.toTypedArray()
            ?: return@script null
        val command = (scriptItems.first().value as? String)?.trim()?.let { command ->
            when (command.uppercase()) {
                "SCRP" -> command
                "ISCR" -> command
                "RSCR" -> command
                else -> null
            }
        }
        Script(command, scriptItems, range)
    }.toTypedArray()
}

private infix fun Range.inside(other: Range): Boolean {
    return inRange(this, other)
}