package com.bedalton.creatures.caos.utils

import com.bedalton.creatures.caos.exceptions.CaosInvalidTokenLengthException
import com.bedalton.creatures.caos.libs.CaosParameter
import com.bedalton.creatures.caos.libs.ICaosParameter
import kotlin.math.pow

@Throws(CaosInvalidTokenLengthException::class)
internal fun token(token: String): Int {
    val chars = token.lowercase().toCharArray()
    if (chars.isEmpty() || chars.size > 4)
        throw CaosInvalidTokenLengthException(chars)
    return token(chars[0].code, chars[1].code, chars[2].code, chars[3].code)
}

/**
 * Takes a CAOS word token, and converts it back to a string
 */
fun token(token: Int): String {
    return "${(token shr 24).toChar()}${((token shr 16) and 0xFF).toChar()}${((token shr 8) and 0xFF).toChar()}${(token and 0xFF).toChar()}"
}

internal fun token(c1: Char, c2: Char, c3: Char, c4: Char): Int =
    token(c1.lowercaseChar().code, c2.lowercaseChar().code, c3.lowercaseChar().code, c4.lowercaseChar().code)

internal fun token(a: Int, b: Int, c: Int, d: Int) = a shl 24 or (b shl 16) or (c shl 8) or d

internal fun binaryToInteger(binary: String): Long {
    val numbers = binary.toCharArray()
    var result = 0L
    for (i in numbers.indices.reversed()) if (numbers[i] == '1') {
        val next = 2.0f.pow((numbers.size - i - 1)).toLong()
        result += next
    }
    return result
}


internal val List<CaosParameter>.formatted
    get() = joinToString(" ") {
        "${it.name} ${it.type.simpleName.let { type -> if (type.startsWith('[')) type else "($type)" }})"
    }

internal val Array<CaosParameter>.formatted
    get() = joinToString(" ") {
        "${it.name} ${it.type.simpleName.let { type -> if (type.startsWith('[')) type else "($type)" }})"
    }

val ICaosParameter.formatted get() = "$name ${typeName.let { type -> if (type.startsWith('[')) type else "($type)" }}"


internal fun listOfTokens(vararg tokenStrings: String): List<Int> {
    return tokenStrings.map {
        token(it)
    }
}

internal fun setOfTokens(vararg tokenStrings: String): Set<Int> {
    return tokenStrings.map {
        token(it)
    }.toSet()
}


internal fun arrayOfTokens(vararg tokenStrings: String): Array<Int> {
    return tokenStrings.map {
        token(it)
    }.toTypedArray()
}
