@JsExport
data class DateComponents(
    val year: Int,
    val monthZeroIndexed: Int,
    val day: Int,
    val hour: Int? = null,
    val minute: Int? = null,
    val seconds: Int? = null,
    val unix: Double? = null,
) {
    fun toISO(offsetHours: Int? = null, offsetMinutes: Int? = null): String {
        val offset = if (offsetHours != null) {
            (if (offsetHours > 0) "+" else "") + offsetHours.toString() + ":" + (offsetMinutes ?: 0).toString()
                .padStart(2, '0')
        } else {
            ""
        }
        val time = if (hour != null || minute != null) {
            "T" + (hour ?: 0) + ":" + (minute ?: 0) + (if (seconds != null) ":$seconds" else "")
        } else {
            ""
        }
        return year.toString() + "-" +
                (monthZeroIndexed + 1).toString().padStart(2, '0') + "-" +
                day.toString() +
                time +
                offset
    }
}

@Suppress("MemberVisibilityCanBePrivate")
object Time {

    val DAYS_OF_THE_WEEK by lazy {
        listOf(
            "Sunday",
            "Monday",
            "Tuesday",
            "Wednesday",
            "Thursday",
            "Friday",
            "Saturday"
        )
    }

    val DAYS_OF_THE_WEEK_SHORT by lazy {
        listOf(
            "Sun",
            "Mon",
            "Tue",
            "Wed",
            "Thu",
            "Fri",
            "Sat"
        )
    }

    fun dayOfTheWeekToInt(value: String?): Int? {
        if (value == null) {
            return null
        }
        var index = DAYS_OF_THE_WEEK.indexOf(value)
        if (index < 0) {
            index = DAYS_OF_THE_WEEK_SHORT.indexOf(value)
        }
        return if (index >= 0) {
            index
        } else {
            null
        }
    }

    val ANY_DAY_OF_THE_WEEK_REGEX by lazy {
        "Sun(day)?|Mon(day)?|Tue(sday)?|Wed(nesday)?|Thu(rsday)?|Fri(day)?|Sat(urday)?"
            .toRegex(RegexOption.IGNORE_CASE)
    }

    val MONTHS by lazy {
        listOf(
            "January",
            "February",
            "March",
            "April",
            "May",
            "June",
            "July",
            "August",
            "September",
            "October",
            "November",
            "December"
        )
    }

    val MONTHS_SHORT by lazy {
        listOf(
            "Jan",
            "Feb",
            "Mar",
            "Apr",
            "May",
            "Jun",
            "Jul",
            "Aug",
            "Sep",
            "Oct",
            "Nov",
            "Dec"
        )
    }



    fun monthToIntZeroIndexed(value: String?): Int? {
        if (value == null) {
            return null
        }
        var index = MONTHS.indexOf(value)
        if (index < 0) {
            index = MONTHS_SHORT.indexOf(value)
        }
        return if (index >= 0) {
            index
        } else {
            null
        }
    }

    val ANY_MONTH_REGEX by lazy {
        "(Jan(uary)?|Feb(ruary)?|Mar(ch)?|Apr(il)?|May|Jun(e)?|Jul(y)?|Aug(ust)?|Sep(tember)?|Oct(ober)?|Nov(ember)?|Dec(ember)?)".toRegex(
            RegexOption.IGNORE_CASE
        )
    }
}