@file:Suppress("unused")

package com.bedalton.creatures.caos.validators


import com.bedalton.creatures.caos.libs.CommandType
import com.bedalton.creatures.caos.libs.CommandType.*
import com.bedalton.creatures.caos.libs.ICaosParameter

internal object ErrorFormatter {

    internal fun outOfVariantError(command: String, variantString: String): String {
        return "${command.uppercase()} is available in [$variantString] variants only"
    }

    internal fun typeMismatchError(command: String, expected: ICaosParameter, actualType: String): String {
        return "Parameter(${expected.index + 1}) '${expected.name}' should be ${expected.typeName}; Found $actualType (in $command)"
    }

    internal fun variableTypeError(variableType: String, variants: String): String {
        val formattedVarType = variableType.trimEnd('x', 'X').uppercase().padEnd(4, 'x')
        return "$formattedVarType variables are only available in [$variants] variants"
    }


    /**
     * Formats an error when a command is not found
     */
    internal fun commandNotFoundError(
        variant: String,
        commandTokenIn: String,
        commandType: CommandType
    ): String {
        val commandToken = commandTokenIn.uppercase().trim(' ', '.')
        val command = variantsByCommand.command[commandToken].orEmpty()
        val rvalue = variantsByCommand.rvalue[commandToken].orEmpty()
        val lvalue = variantsByCommand.lvalue[commandToken].orEmpty()

        // Get error on incorrect command type if any
        getOtherCommandError(
            variant = variant,
            commandToken = commandToken,
            commandType = commandType,
            variantsForCommand = command,
            variantsForRvalue = rvalue,
            variantsForLvalue = lvalue
        )?.let {
            return it
        }

        // Get variants where command is valid if any
        val variants = when (commandType) {
            RVALUE -> rvalue
            LVALUE -> lvalue
            COMMAND -> command
        }

        // If command is not found in other variants, return error stating invalid
        if (variants.isEmpty()) {
            return "'$commandToken' is not a valid ${commandType.value} in variant $variant"
        }
        // Command was found in other variants. Report it
        return "'$commandToken' is only available in [${formatVariants(variants)}]"
    }

    /**
     * Formats an error if command exists outside of expected command type (rvalue,lvalue, etc)
     */
    private fun getOtherCommandError(
        variant: String,
        commandToken: String,
        commandType: CommandType,
        variantsForCommand: List<String>,
        variantsForRvalue: List<String>,
        variantsForLvalue: List<String>
    ): String? {
        // Create mutable list of other types of commands for this command token
        val otherCommandType = mutableListOf<String>()

        // Find if command exists anywhere in variant as a Rvalue, lvalue or command
        if (variantsForCommand.contains(variant))
            otherCommandType.add("command")
        if (variantsForRvalue.contains(variant))
            otherCommandType.add("rvalue")
        if (variantsForLvalue.contains(variant))
            otherCommandType.add("lvalue")

        // If not found in variant at all, return null
        if (otherCommandType.isEmpty())
            return null

        // Join other types as a single string.
        // Should only be two value in the list,
        // otherwise it would have been found as valid
        val commandTypesAsString = otherCommandType.joinToString(" and ")

        // choose 'a' or 'an' as needed for expected type
        val anExpected = if (commandType == COMMAND) "a" else "an"
        // choose 'a' or 'an' as needed for actual types
        val anActual = if (commandTypesAsString.startsWith("command")) "a" else "an"
        // Return formatted error
        return "'$commandToken' is not $anExpected ${commandType.commonName} but $anActual $commandTypesAsString in variant [$variant]"
    }

    internal fun formatVariants(variants: Array<String>): String {
        val numVariants = variants.size
        return when {
            numVariants == 1 -> variants.first()
            numVariants == 2 && variants.intersect(listOf("C3", "DS")).size == 2 -> "C3+"
            numVariants == 3 && variants.intersect(listOf("C3", "DS", "SM")).size == 3 -> "C3+"
            numVariants == 3 && variants.intersect(listOf("CV", "C3", "DS")).size == 3 -> "CV+"
            numVariants == 4 && variants.intersect(listOf("CV", "C3", "DS","SM")).size == 4 -> "CV+"
            numVariants == 4 && variants.intersect(listOf("C2", "CV", "C3", "DS")).size == 4 -> "C2+"
            numVariants == 5 && variants.intersect(listOf("C2", "CV", "C3", "DS", "SM")).size == 5 -> "C2+"
            else -> variants.joinToString(",")
        }
    }
    internal fun formatVariants(variants: List<String>): String {
        val numVariants = variants.size
        return when {
            numVariants == 1 -> variants.first()
            numVariants == 2 && variants.intersect(listOf("C3", "DS")).size == 2 -> "C3+"
            numVariants == 3 && variants.intersect(listOf("CV", "C3", "DS")).size == 3 -> "CV+"
            numVariants == 4 && variants.intersect(listOf("C2", "CV", "C3", "DS")).size == 4 -> "C2+"
            else -> variants.joinToString(",")
        }
    }
}