/**
 * Represents a single position within a text document
 */
@Serializable(with = PositionSerializer::class)
@JsExport
interface Position {
    /**
     * Line position in a document (zero-based).
     */
    @JsName("line")
    val line: Int

    /**
     * Character offset on a line in a document (zero-based). Assuming that the
     * line is represented as a string, the character value represents the gap
     * between the character and character + 1.
     * If the character value is greater than the line length it defaults back to the line length.
     */
    @JsName("character")
    val character: Int
}

/**
 * Simple implementation of the Position interface
 */
@JsExport
@Serializable
data class PositionImpl(
    override val line: Int,
    override val character: Int,
): Position

/**
 * A range in a text document expressed as (zero-based) start and end positions.
 *
 * If you want to specify a range that contains a line including the line ending
 * character(s) then use an end position denoting the start of the next line.
 * For example:
 * ```ts
 * {
 *     start: { line: 5, character: 23 }
 *     end : { line 6, character : 0 }
 * }
 * ```
 */
@Serializable(with = RangeSerializer::class)
expect interface Range {
    /**
     * The range's start position
     */
    val start: Position

    /**
     * The range's end position.
     */
    val end: Position
}

/**
 * A range in a text document expressed as (zero-based) start and end positions.
 *
 * If you want to specify a range that contains a line including the line ending
 * character(s) then use an end position denoting the start of the next line.
 * For example:
 * ```ts
 * {
 *     start: { line: 5, character: 23 }
 *     end : { line 6, character : 0 }
 * }
 * ```
 */
@Serializable
data class RangeImpl(
    /**
     * The range's start position
     */
    override val start: Position,
    /**
     * The range's end position.
     */
    override val end: Position,
): Range


/**
 * Interfaces for objects with an indexed range within a document
 */
expect interface HasRange {
    @JsName("textRange")
    val textRange: RangeWithIndex
}


/**
 * Inlay hint information.
 *
 * @since 3.17.0
 */
@Serializable(with = InlayHintSerializer::class)
expect interface InlayHint {
    /**
     * The position of this hint.
     */
    val position: Position

    /**
     * The label of this hint. A human-readable string or an array of
     * InlayHintLabelPart label parts.
     *
     * *Note* that neither the string nor the label part can be empty.
     */
    val label: String

    /**
     * The kind of this hint. Can be omitted in which case the client
     * should fall back to a reasonable default.
     */
    val kind: Int?

    /**
     * Optional text edits that are performed when accepting this inlay hint.
     *
     * *Note* that edits are expected to change the document so that the inlay
     * hint (or its nearest variant) is now part of the document and the inlay
     * hint itself is now obsolete.
     */
    val textEdits: Array<TextEdit>?

    /**
     * The tooltip text when you hover over this item.
     */
    val tooltip: String?

    /**
     * Render padding before the hint.
     *
     * Note: Padding should use the editor's background color, not the
     * background color of the hint itself. That means padding can be used
     * to visually align/separate an inlay hint.
     */
    val paddingLeft: Boolean?

    /**
     * Render padding after the hint.
     *
     * Note: Padding should use the editor's background color, not the
     * background color of the hint itself. That means padding can be used
     * to visually align/separate an inlay hint.
     */
    val paddingRight: Boolean?
//    /**
//     * A data entry field that is preserved on an inlay hint between
//     * a `textDocument/inlayHint` and a `inlayHint/resolve` request.
//     */
//    val data: Any?
}


expect interface ITextEdit

/**
 * A text edit applicable to a text document.
 */
@Serializable(with = TextEditSerializer::class)
expect interface TextEdit: ITextEdit {
    /**
     * The range of the text document to be manipulated. To insert
     * text into a document create a range where start === end.
     */
    @JsName("range")
    val range: Range

    /**
     * The string to be inserted. For delete operations use an
     * empty string.
     */
    @JsName("newText")
    val newText: String
}

@Serializable
data class TextEditImpl(
    override val range: Range,
    override val newText: String,
): TextEdit


@JsExport
@Serializable
data class InsertReplaceEdit(
    /**
     * The string to be inserted.
     */
    @JsName("newText")
    val newText: String,

    /**
     * The range if the "insert" action is requested
     */
    @JsName("insert")
    val insert: Range,

    /**
     * The range if the "replace" action is requested.
     */
    @JsName("replace")
    val replace: Range,
): ITextEdit

/**
 * Converts an Antlr token to a standard Position object
 */
internal fun Token.toPosition(): Position {
    return PositionImpl(
        this.line - 1,
        this.charPositionInLine
    )
}


/**
 * Represents a range within a documents, with the
 * addition of its absolute start and end character indices within the file
 */
@Serializable(with = RangeWithIndexSerializer::class)
interface RangeWithIndex: Range {
    @JsName("startIndex")
    val startIndex: Int

    @JsName("endIndex")
    val endIndex: Int

    @JsName("parserIndex")
    val parserIndex: Int?
}

/**
 * Concrete implementation of an RangeWithIndex which represents a range within a documents,
 * with the addition of its absolute start and end character indices within the file
 */
@JsExport
@Serializable
data class RangeWithIndexImpl(
    override val start: Position,
    override val end: Position,
    override val startIndex: Int,
    override val endIndex: Int,
    override val parserIndex: Int? = null,
): RangeWithIndex {

    @JsName("withParserRuleContext")
    internal constructor(ctx: ParserRuleContext, parserIndex: Int? = null): this(
        startIndex = ctx.start!!.startIndex,
        endIndex = ctx.stop?.stopIndex ?: ctx.start!!.stopIndex,
        start = PositionImpl(
            line = ctx.start?.line?.let { it - 1 } ?: 0,
            character = ctx.start?.charPositionInLine ?: 0
        ),
        end = PositionImpl(
            line = ctx.stop?.line?.let { it - 1 } ?: 0,
            character = if (ctx.start!!.line == ctx.stop!!.line) {
                maxOf(0, ctx.start!!.charPositionInLine + ctx.trueText.length)
            } else {
                ctx.stop!!.charPositionInLine
            } - 1
        ),
        parserIndex = parserIndex
    )

    @JsName("withStartEndTokens")
    internal constructor(start: Token, end: Token, parserIndex: Int? = null): this(
        startIndex = start.startIndex,
        endIndex = end.stopIndex,
        start = PositionImpl(
            line = start.line - 1,
            character = start.charPositionInLine
        ),
        end = PositionImpl(
            line = end.line - 1,
            character = end.charPositionInLine
        ),
        parserIndex = parserIndex
    )

    @JsName("withStartEndTokensAndOffset")
    internal constructor(
        start: Token,
        end: Token,
        parserIndex: Int?,
        offsetIndex: Int,
        offsetLine: Int,
        offsetColumn: Int = 0,
    ): this(
        startIndex = start.startIndex + offsetIndex,
        endIndex = end.stopIndex + offsetIndex,
        start = PositionImpl(
            line = (start.line - 1) + offsetLine,
            character = start.charPositionInLine + (if (start.line == 1) offsetColumn else 0)
        ),
        end = PositionImpl(
            line = (end.line - 1) + offsetLine,
            character = if (start.line == end.line) {
                val offsetColumnMod = (if (end.line == 1) offsetColumn else 0)
                val character = start.charPositionInLine + (end.stopIndex - start.startIndex) + offsetColumnMod
                maxOf(0, character)
            } else {
                end.charPositionInLine
            }
        ),
        parserIndex = parserIndex
    )
}

fun RangeWithIndex.toRange(): Range {
    return RangeImpl(
        start = start,
        end = end
    )
}