private fun dismissTokensIfUsed(currentCommand: ICaosCommand?, tokens: List<CommandToken>): List<CommandToken> {
    if (currentCommand == null) {
        return tokens
    }
    var tokensTemp = tokens.map { t -> token(t.text.lowercase()) }
    val commandTokens = currentCommand.command.lowercase()
        .split(' ')
        .map { c -> token(c) }
    val startIndex = tokensTemp.indexOf(commandTokens[0])
    if (startIndex < 0) {
        return tokens
    }
    val availableTokens = min(commandTokens.size, tokensTemp.size - startIndex)
    tokensTemp = tokensTemp.slice(startIndex..tokensTemp.lastIndex)
    var i = 0
    while (i < availableTokens) {
        if (tokensTemp[i] != commandTokens[i]) {
            return tokens
        }
        i++
    }
    if (i == tokens.size - 1) {
        return emptyList()
    }
    return tokens.slice(i + 1..tokens.lastIndex)
}

private fun <T : HasRange> getClosestItem(inRangeCalls: List<T>, lineNumber: Int, column: Int): Closest<T>? {

    if (inRangeCalls.isEmpty()) {
        return null
    }
    // Combine call with distance to lineNumber/Column
    var distanced: List<Distanced<T>> = inRangeCalls.map { call ->
        Distanced(
            item = call,
            distance = getDistance(call.textRange, lineNumber, column)
        )
    }
    if (distanced.isEmpty()) {
        return null
    }
    // Find all commands on same line
    val sameLine: List<Distanced<T>> = distanced.filter { c -> c.distance.lineOffset == 0 }
    if (sameLine.isNotEmpty()) {
        // Sort by column distance, and return nearest
        var index = 0
        var i = 0
        while (i < sameLine.size) {
            val item = sameLine[i]
            val thisColumn = item.item.textRange.start.character
            if (thisColumn > column) {
                break
            }
            index = i++
        }
        val maxItems = min(6, index)
        val prevItems: MutableList<CommandToken> = mutableListOf()
        if (index > 0) {
            var j = 0
            while (j <= maxItems) {
                val prevIndex = index - j++
                val prevItem = sameLine[prevIndex].item
                if (prevItem is CommandToken) {
                    prevItems.add(prevItem)
                } else {
                    break
                }
            }
        }
        return Closest(
            closest = sameLine[index].item,
            previous = prevItems.reversed()
        )
    }

    // Sort distanced by
    distanced = distanced.sortedWith { a: Distanced<T>, b: Distanced<T> ->
        val lineDistance = a.distance.lineOffset - b.distance.lineOffset
        if (lineDistance == 0) {
            a.distance.columnOffset - b.distance.columnOffset
        } else {
            lineDistance
        }
    }
    var min: Distanced<T> = distanced[0]

    // Search all distanced
    for (call in distanced) {
        // Distanced is sorted by line number
        // So a change in line means it is guaranteed to be further away
        if (call.distance.lineOffset > min.distance.lineOffset) {
            break
        }
        // Grab closest
        if (call.distance.columnOffset < min.distance.columnOffset) {
            min = call
        }
    }
    // Return the closest call
    return Closest(
        closest = min.item,
        previous = emptyList()
    )
}


private fun getDistance(textRange: RangeWithIndex, lineNumber: Int, column: Int): Distance {
    return Distance(
        lineOffset = lineNumber - textRange.start.line,
        columnOffset = if (lineNumber == textRange.start.line) {
            column - textRange.start.character
        } else {
            textRange.start.character
        }
    )
}


@JsExport
interface CursorData: Position {
    @JsName("command")
    val command: ICaosCommand?
    @JsName("missing")
    val missing: Array<ICaosParameter>
    @JsName("closestParameter")
    val closestParameter: ICaosParameter?
    @JsName("beforeText")
    val beforeText: String?
    override val line: Int
    override val character: Int
    @JsName("previousTokens")
    val previousTokens: Array<CommandToken>
    @JsName("closestItem")
    val closestItem: ParserItem<*>?
    @JsName("eqValuesList")
    val eqValuesList: CaosValuesList?
    @JsName("inEqualityStatement")
    val inEqualityStatement: Boolean
}

@JsExport
data class CursorDataImpl(
    override val command: ICaosCommand?,
    override val missing: Array<ICaosParameter>,
    override val closestParameter: ICaosParameter?,
    override val beforeText: String?,
    override val line: Int,
    override val character: Int,
    override val previousTokens: Array<CommandToken>,
    override val closestItem: ParserItem<*>?,
    override val eqValuesList: CaosValuesList?,
    override val inEqualityStatement: Boolean
) : CursorData {
    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is CursorDataImpl) return false

        if (command != other.command) return false
        if (!missing.contentEquals(other.missing)) return false
        if (closestParameter != other.closestParameter) return false
        if (beforeText != other.beforeText) return false
        if (line != other.line) return false
        if (character != other.character) return false
        if (!previousTokens.contentEquals(other.previousTokens)) return false
        if (closestItem != other.closestItem) return false
        if (eqValuesList != other.eqValuesList) return false
        if (inEqualityStatement != other.inEqualityStatement) return false

        return true
    }

    override fun hashCode(): Int {
        var result = command?.hashCode() ?: 0
        result = 31 * result + missing.contentHashCode()
        result = 31 * result + (closestParameter?.hashCode() ?: 0)
        result = 31 * result + (beforeText?.hashCode() ?: 0)
        result = 31 * result + line
        result = 31 * result + character
        result = 31 * result + previousTokens.contentHashCode()
        result = 31 * result + (closestItem?.hashCode() ?: 0)
        result = 31 * result + (eqValuesList?.hashCode() ?: 0)
        result = 31 * result + inEqualityStatement.hashCode()
        return result
    }

}

private data class Closest<T : HasRange>(
    val closest: T,
    val previous: List<CommandToken>,
)

private data class Distanced<T : HasRange>(
    val item: T,
    val distance: Distance,
)

private data class Distance(
    val lineOffset: Int,
    val columnOffset: Int,
)